quests[25215] = { id = 25215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Distracting Scent", description = "Predators will smell these dead naga from nearly a mile away. Soon we'll find ourselves fighting just to get in and out of the cave. Care to help me clean up?\n\nJust over the ridge to the south is Glimmerdeep Gorge. If you drag the corpses from the eastern exit of the cave over there to the gorge and cut them loose, the wildlife will pick them clean before they hit the sea floor. Just steer clear of the sharks as much as you can.", completion = "It shouldn't take long to cleanse the water. Thank you for your help.", objectives = "Drag 3 Dead Zin'jatar Raiders into the open water over Glimmerdeep Gorge to the south.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25216] = { id = 25216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Sambino", description = "If you're heading down the trench, I'd like you to check in one of our novice members for me.\n\nHis name is Sam, but he's likely to embellish it a bit. He doesn't really understand how members of the Earthen Ring work, but he tries hard, so we try to give him the benefit of the doubt.\n\nDon't get too wrapped up in helping him with his crazy schemes. Just make sure he's still in one piece and let me know so that I can have a little peace of mind.", completion = "Another fan of the Great Sambino! Come all this way for an autograph perhaps? I'm far too busy to be signing anything... move along now.", objectives = "Find \"Sam\" at the western end of Silver Tide Trench.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25217] = { id = 25217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totem Modification", description = "Okay, I'll let you in on the real work, since you're looking at me so desperately.\n\nThis rock is untapped! It's probably richer than a trade prince during a great war! I need samples. More samples. Samples from everywhere!\n\nI've modified my earth totems to drill through the sand and store samples of the rock underneath. Go find a nice spot and plant one.\n\nThe shaking and rumbling will probably attract all the cute, curious wildlife, so maybe you can make some friends while you're at it.", progress = "Bah! There's sand in my helmet. It itches!", completion = "Another sample. Brilliant! The rocky riches of the sea shall soon be mine!", objectives = "Plant one of Sambino's modified totems in the sand of Silver Tide Trench.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25218] = { id = 25218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Undersea Inflation", description = "Fine! Fine. You argued me into it. You can help.\n\nI'm leaking air worse than a zeppelin stuffed with quilboar! My air valve must have come loose somewhere in the trench.\n\nI brought spare air balloons - make yourself useful and go fill one up, will ya? And find my valve! I'll need that too.\n\nI bet the crabs snatched it up... pinchy, greedy little things.", progress = "If only air weren't so darn floaty! Or if only those water breathing spells came with stylish helmets! Either would do nicely.", completion = "Ya know, I should have given you a weight belt so that you wouldn't just float away, air balloon and all. Lucky for me you came down here with armor and all! Hah!", objectives = "Fill one of Sambino's Air Balloons and find his Lost Air Valve.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25219] = { id = 25219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't be Shellfish", description = "I'm researching snails.\n\nYes. Snails. When you're done laughing, maybe you can help.\n\nI'm sure you noticed the gigantic shellfish across the ridge... well, I'm pretty sure there's something inside it. It has several points that can only be mouths or entrances of some kind, and I've seen those sifting snails squeezing in and out.\n\nI'm thinking that we might be able to use the snails to gain entrance ourselves. That's the theory anyway.", progress = "I know, this isn't the most desirable work, but can you really help but be curious about that shell? It's immense. There has to be something more to it.", completion = "Thank you. Seriously. If I would have had to endure another shipwreckee laughing at me, I swear I would have gored someone.\n\nI'll let you know if I come up with anything.", objectives = "Collect 10 Coilshell Sifters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25220] = { id = 25220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slippery Threat", description = "Been attacked by any of the eels along the ridges yet? If not, you will. They are vicious, bloodthirsty little monsters. They don't seem to show much of any preference in what they're biting.\n\nIf you're going out into the valley, I'd appreciate if you thinned their population a bit. Not everyone here is as well equipped as you - we might not come back with just scratches.", completion = "Thank you, {class}. There are still much bigger predators we'll have to keep an eye out for, but this will at least give us a bit of peace of mind around the cave.", objectives = "Kill 12 Spiketooth Eels.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25221] = { id = 25221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rundown", description = "They're getting away!\n\nThese are the same naga that attacked the boats and carried away our friends. We cannot let them escape!\n\nTake these spears and run them down with that seahorse of yours... don't waste your time dismounting, just keep after them and kill all that you can with the spears.\n\nI will try to hunt down that Fathom-Lord. Meet me at the far end of the ledge when you're done.", progress = "Our other allies are in the cave below. Things look safe from here, but it's hard to be certain.\n\nDid you do as I asked of you?", completion = "Swift work. Very impressive.\n\nThat Fathom-Lord got away... I don't see him anywhere. He's most certainly the key to finding our captured friends.\n\nI will hunt him down. He cannot stay hidden for long.", objectives = "Use Toshe's Hunting Spear to run down 20 fleeing Zin'jatar naga.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25222] = { id = 25222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silver Tide Hollow", description = "Most of the other Earthen Ring that escaped the massacre on the boats have taken shelter in a cave a short swim down from the ridge. It's tucked midway up a huge rock formation, west of Nespirah, the gigantic shell on the horizon.  I need you to make sure they're okay. There's no telling how many naga might have attacked them as well.\n\nI'm going to hunt down that Fathom-Lord. I'll send word if I find the rock he's hiding under.", completion = "A friendly face! Welcome!\n\nVery kind of you to come check on us. We're fine. A naga scouting force did find us, but I'm pretty sure none escaped. We should be safe for now.", objectives = "Seek out Felora Firewreath in Silver Tide Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25223] = { id = 25223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trial By Fire", description = "I'd love to say that with the tides turning against us in Hyjal, every recruit helps our cause and so on... but to be perfectly blunt, most of you are nothing but a burden.\n\nIf I had a copper for every peasant who got too scared when the cataclysm hit and now wishes to join our side... well, let's just say I'd be a rich woman.\n\nFortunately we have checks in place to separate the wheat from the chaff.  Go and prove yourself to the fiery instructors below.  Hopefully you'll do better than the others.", completion = "I suppose your abilities are... suitable.  Color me impressed.", objectives = "Defeat 8 Fiery Instructors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25224] = { id = 25224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Bloom", description = "It is customary for new recruits to be sent on a difficult or sometimes impossible task.  I was sent to obtain a black dragon's scale; last year's instructors demanded a feather from a phoenix.\n\nYour lot has it relatively easy.  Find me a handful of flame blossoms.\n\nThey grow around here in relative abundance.  Oh, right.  There will be a gigantic core hound roaming the fields to keep things interesting.  Do your best to avoid him.", progress = "Yes, Yshkaldamus?", completion = "So you managed to pass this part of the test without getting yourself eaten by Smolderos or being incinerated by the fire elementals?\n\nI suppose I should congratulate you on ascending the lowest rung of our ladder.\n\nWell... congratulations, recruit!", objectives = "Obtain 5 Flame Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25225] = { id = 25225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oil Change", description = "The lubricant in these shredders is useless. What we need is some good ol' Kajaro 0W Grade Oil!\n\nYou know what has that kind of oil? KTC Oil Bots! You know where you can find them? At the KTC Oil Platform to the northwest!", objectives = "Collect 6 Kajaro 0W Grade Oil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25226] = { id = 25226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill Chip Endale Tracking Quest" }
quests[25227] = { id = 25227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thonk", description = "<Oh, sweetie, I just remembered!/Sorry if I've been mean to you.  Sometimes I get a little jealous when other women come into town> as I'm a little insecure about my appearance.;\n\nMy VERY good friend Thonk works in the guard tower on that cliff, just to the northwest of Razor Hill.  He said something about a river overflowing, lots of work to be done, and so on.  I wasn't really paying attention... I was staring into those deep brown eyes of his.\n\n<What, we can't see other people?/Thanks.>", completion = "Gail sent you?  Did... did she say anything about me?", objectives = "Report to Thonk on the guard tower northwest of Razor Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25228] = { id = 25228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prophecies Of Doom", description = "Harbingers of doom are nothing new on the streets of Orgrimmar, but I'm worried about this latest batch. These people are organized and they've attracted a lot of attention in the Drag, where they seem to congregate.\n\nI've thought about rounding them up or otherwise disrupting their activities, but that will just drive them underground. We need to find out more about them. Would you go to the Drag, listen to what these doomsayers are spreading, and gather any literature you can find about their ideas?", progress = "Well, did you find out anything?", completion = "<Torek reads over the scrolls you collected.>\n\nWhoever these people are, they really mean to gain a following. It looks like they're having quite a bit of success. They can't be allowed to incite the citizens of Ogrimmar to panic and hysteria. We must discourage interest in this group and learn as much about it as we can.", objectives = "Listen to a speech given by a Doomsayer in the Drag and obtain copies of the pamphlets \"Elemental Fire for the Soul\", \"What Does 'The End of All Things' Mean for Me?\", and \"Finding Security and Comfort in a Doomed World\".", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25229] = { id = 25229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Few Good Gnomes", description = "Our engineers have been working on getting our battle machines ready for our assault on Gnomeregan, but we're out of pilots!\n\nWe've developed a device called the Motivate-a-Tron, which prevents distraction from other sources and gives the gnome the courage to enlist.\n\nAfter motivating a few Gnome Citizens, lead them out to Captain Tread Sparknozzle out at Steelgrill's Depot, just south of Ironforge.\n\nOh, and be careful. The device is still a little experimental.", objectives = "Recruit Gnome Citizens from Tinker Town using the Motivate-a-Tron and lead them to Captain Tread Sparknozzle at Steelgrill's Depot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25230] = { id = 25230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Than Illness", description = "We've found a brood of dragon whelps gathered off the road to the north, and they show the same illness as the stags.\n\nGreen dragons are not simple beasts of nature, but the very guardians of the wild. They are magical creatures, and to see them ill as well implies this is a dangerous threat.\n\nWe must stop this from spreading further through any means. Slay the infected whelps, {name}, and return to me.", completion = "These events disturb me greatly. My study of the antlers while you were gone has revealed little.\n\nWe must find some way to fix this...", objectives = "Kill 10 Noxious Whelps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25231] = { id = 25231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Southseas Scum", description = "Even now, Aggra and Kilag assault the docks to clear the way for Thrall to engage the Trade Prince. The plan is for you to assist in that attack, but first, we must ensure that Gallywix's Southsea mercenaries do not reinforce him.\n\nGo down into the Slave Pits and make certain that they don't!", objectives = "Slay 6 Southsea Mercenaries.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25232] = { id = 25232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Burning Blade", description = "I've been sent to investigate the presence of more Burning Blade agents here in Durotar.  To the northeast, you'll find a cave where the organization trains their new recruits.  I'm interested in what exactly they are teaching these neophytes.\n\nI only tell you this because you seem to be looking for work.  If you're interested in a little coin, sack the cave and return with their spellscrolls.\n\nThe cave is somewhat hidden: exit Razor Hill from the east, and follow the canyon's eastern ridge.", progress = "The scrolls, {name}, the scrolls!", completion = "This is quite interesting.  These rites aren't all that different from the spells which are taught to Horde warlocks.  This merits further investigation!", objectives = "Obtain 6 Burning Blade Spellscrolls from members of the Burning Blade in Dustwind Cave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25233] = { id = 25233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "End of the Supply Line", description = "Cho'gall's Twilight Proveditors swear a blood oath that they will get their supplies through to the front, pledging a pound of their own considerable flesh for every pound of supplies they fail to deliver. They would rather die than fail.\n\nSee to it that they do both.", completion = "Well done! The chaos we sow back here will be felt up and down the chain of command.", objectives = "Slay 4 Twilight Proveditors at Wolf's Run in Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25234] = { id = 25234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In the Rear With the Gear", description = "Prisoners of the Twilight's Hammer are forced to lug around sundries for the war effort, like common pack animals. I want those supplies, and if we can free a few poor souls from the Hammer's shadowy grip, all the better.\n\nKill the slave drivers along the road to our south and nearby slaves should make a break for it.\n\nSearch the packs they leave behind for anything valuable, and destroy anything you can't carry.", progress = "Have you created some havoc down there, {name}?", completion = "<Jadi kicks open one of the crates and picks up a curved dagger within. She immediately winces in pain.>\n\nAugh! Cursed - this metal is cursed - it bites!\n\n<When the dagger falls to the ground, it shatters, as if made of brittle glass.>\n\nWhat demented workmanship is this? {name}, I've never fought any foe like this before.", objectives = "Collect 36 Twilight Supplies left behind from freed Twilight Slaves.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25235] = { id = 25235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vulgar Vul'Gol", description = "Hail, {class}. Care to lend a hand for the people of Darkshire?\n\nThere's a huge ogre mound just down the hill there. The Splinter Fist ogres usually keep to themselves, but they've got a bad habit of attacking travelers. Just the other day I saw one drag off a poor man's horse for food... he was lucky it left him behind!\n\nThe Night Watch wants to only risk its few members in the defense of more immediate threats, me included. But if you kill some of those ogres for me, I'll pay you for your deed.", progress = "If you'd rather just sit around camp and have a drink or two, that's fine too, I guess.", completion = "I saw you drop a few of them from here. Nice work.\n\nHere's your reward, on behalf of the Night Watch.", objectives = "Kill 15 Splinter Fist Ogres of any kind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25236] = { id = 25236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunder Down Under", description = "Our army needs water, and luckily the elements gave us plenty of that when the cataclysm hit.  The water that filled up the canyon to the southwest should do the trick.\n\nUnfortunately, the corpses of thunder lizards still sit at the bottom of the canyon, and their electrical discharges are a bit too dangerous.  I've got grunts that can lift them out of the water, but we need someone agile enough to attach the other end of the rope.  Are you my <man/woman>, {name}?", completion = "The electricity was only one of the dangers.  If those carcasses rot too long under the water, that entire source becomes undrinkable.\n\nWell done, {class}.", objectives = "Attach a Mageweave Tether to 8 Drowned Thunder Lizards in Thunder Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25237] = { id = 25237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tears of Stone", description = "As you witnessed, the dragon Ysondre has told us that the tears of the land can seal the portal from which this corruption stems.\n\nWeeks ago, in the glade to the west, I saw the mountain giants distraught. They raged in frustration and wept, and their tears fell upon the stones as shining crystals.\n\nThough the giants weep no more, these stonetears must be what Ysondre referred to; a source of nature's purity. We must gather them.", progress = "The tears are among the very rocks that the giants themselves rise from. There should be loose ones near the base of these large monoliths.", completion = "Thank you once again, {name}. I will prepare these for our final task.", objectives = "Collect 7 Stonetears.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25238] = { id = 25238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strength Ring Flag" }
quests[25239] = { id = 25239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Might", progress = "You seek to continue down the path of might?", completion = "You continue to prove yourself, {name}.  Accept this, not as a gift, but as a tool for the fight against the Scourge." }
quests[25240] = { id = 25240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Might", progress = "You seek to continue down the path of might?", completion = "You continue to prove yourself, {name}.  Accept this, not as a gift, but as a tool for the fight against the Scourge." }
quests[25241] = { id = 25241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Land, Corrupted", description = "The cliff giants of Feralas are extensions of the earth itself, {name}. When nature thrives, they are benevolent protectors and peaceful guardians.\n\nBut as the forest is tainted, so too are they.\n\nIf the corruption has spread to them, they will lash out at the wildlife and their own kind, causing great destruction. You must destroy any corrupted giants you come across.", completion = "The spirits of these guardians will return in time, {name}. You've freed them to move on in nature's cycle.\n\nNow it falls to us to make sure that cycle is free of corruption and needless suffering.", objectives = "Kill 7 Corrupted Cliff Giants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25242] = { id = 25242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Might", progress = "You seek to continue down the path of might?", completion = "You are a true champion of our cause, {name}.  None can claim to be more dedicated to the struggle than you.\n\nIt is rumored that the minions of the Scourge fear you more than they do the Lich King himself.  You are might incarnate.\n\nAccept this humble gift as a reward for your many triumphs." }
quests[25243] = { id = 25243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "She Loves Me, She Loves Me NOT!", description = "Oh, sweetie! You're never going to guess who's down in the slave pits to the north.\n\n<Sassy shakes her head sadly at you.>\n\nCandy's down there, and she's working for the Trade Prince. She dropped you like a bad habit and now she's working for the other team. but it gets worse. Since you \"dealt\" with Chip, she's shmoozin' up to the Trade Prince!\n\nI don't know about you, but if she were my absolutely-not-fake girlfriend, I'd rip her fickle heart right out of her chest.", progress = "What did you decide to do, hon?", completion = "I'm sure she deserved it, {name}. She should never have betrayed you like that.\n\nIt gives me the shivers to think that she might have kissed that monster, the Trade Prince!", objectives = "Rip the Fickle Heart from out of Candy Cane's chest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25244] = { id = 25244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Kind of Name is Candy, Anyway?", description = "Can you believe that Candy Cane! You know up until you \"dealt\" with Chip, she was tryin' to start a partner brand with him. Now she's shmoozin' up to the Trade Prince!\n\nI just can't get over the fact that she betrayed you like that with your absolutely-not-fake boyfriend. Maybe you should head down into the Slave Pits and take care of her once and for all?", completion = "Serves her right for stealing your man in the first place.", objectives = "Slay Candy Cane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25245] = { id = 25245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill Candy Cane Tracking Quest" }
quests[25246] = { id = 25246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Change of Heart", progress = "You seek to change the path you walk, {name}?", completion = "May you find what you're looking for, <brother/sister>." }
quests[25247] = { id = 25247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Change of Heart", progress = "You seek to change the path you walk, {name}?", completion = "May you find what you're looking for, <brother/sister>." }
quests[25248] = { id = 25248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Change of Heart", progress = "You seek to change the path you walk, {name}?", completion = "May you find what you're looking for, <brother/sister>." }
quests[25249] = { id = 25249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Change of Heart", progress = "You seek to change the path you walk, {name}?", completion = "May you find what you're looking for, <brother/sister>." }
quests[25250] = { id = 25250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sealing the Dream", description = "It is ready. Take this, {name}; a beacon of natural essence, blessed by the will of Ysondre.\n\nTo the east, on the other side of the flowing brook, is Dream Bough. There stands the Great Tree, the tallest in Feralas, a sapling of the World Tree itself. A portal to the heart of the Emerald Dream sits in its trunk, and it is this portal you must seal.\n\nThe portal will be guarded, but you must be brave. May the Earth Mother watch over you.", completion = "The corruption has been stemmed! The forest can begin to heal now.\n\nMay you have the blessing of the Earth Mother wherever you go, friend.", objectives = "Use Ysondre's Tear to seal the portal at Dream Bough.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25251] = { id = 25251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Final Confrontation", description = "{name}, this is it! Thrall's down at the Gallywix Docks fighting the Trade Prince right now!\n\nYou gotta jump into your Ultimate Footbomb Uniform and get over there!", progress = "{name}, you have to go deal with the Trade Prince before it's too late!", completion = "You did it! You did it!\n\nWe're saved, {name}!", objectives = "Get into the Ultimate Footbomb Uniform and then deal with Trade Prince Gallywix.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25252] = { id = 25252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rulers of Dire Maul", description = "Now that we've put the hurt on them at the ruins, it's time to attack the ogres in their own territory.\n\nThe Gordok are the \"upper class\" of the Gordunni clan, chosen to defend Dire Maul. They'll know we mean business once we start taking out their strongest members.\n\nNothing fancy here, {name}. Just get out there and crack some Gordok skulls.", completion = "Excellent! Even these fools will soon know that to stand against the Horde means death.", objectives = "Kill 6 Gordok Enforcers and 6 Gordok Ogre-Mages.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25253] = { id = 25253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prophecies Of Doom", description = "Harbingers of doom are nothing new on the streets of Stormwind, but I'm worried about the most recent ones. They've set up shop all over Old Town and they seem well coordinated.\n\nI've thought about rounding them up or otherwise disrupting their activities, but that will just drive them underground. We need to find out as much as we can about them. Would you go to Old Town, hear what idea these doomsayers are spreading, and see if you can collect any of their leaflets?", progress = "What did you encounter in Old Town?", completion = "<Anton reads over the scrolls you collected.>\n\nWhoever put these leaflets together knows how to get attention and from the state of things in Old Town, there's no lack of interest. We must act before they can build a significant following in the city. I fear they'll use their influence to spread panic throughout the city, paralyzing us.\n\nWe've got to get inside the organization and learn as much as possible.", objectives = "Listen to a speech given by a Doomsayer in Old Town and obtain copies of the pamphlets \"Elemental Fire for the Soul\", \"What Does 'The End of All Things' Mean for Me?\", and \"Finding Security and Comfort in a Doomed World\".", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25254] = { id = 25254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signs Of The Times", description = "We've got to do something to reduce interest in this doomsday cult, but I'm hesitant to take much action until we know more about who is behind this group.\n\nI've had my men place markers around heavily traveled areas in Orgrimmar. Take these posters and set them up where you see the markers. They won't discourage the most determined of seekers, but it's a first step in exposing this cult. The Horde has enough to deal with as it is, without people wilfully spreading lies too.", completion = "Well done, {name}. Now we must focus our efforts on discovering more about this cult and freeing the people they've conned into joining.", objectives = "Setup 5 Warning Posters around the Valley of Strength, the Drag, or the Valley of Honor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25255] = { id = 25255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harrying the Hunters", description = "Twilight's Hammer has revealed itself as more than a mere cult. They're a war machine - a swarm of locusts moving up the mountain, devouring anything in their way.\n\nThe parts of the forest they're not setting ablaze are being scoured of life in order to feed the mortal cultists.\n\nWe've got to put a stop to the hunters canvassing Wolf's Run, not only to preserve what wildlife remains but to force the cult to march on empty stomachs. Look south of here, as well as up the road to the east.", completion = "Thank you, {name}. I worry that our actions here may be too little, too late, but nature always has a way of rebuilding itself that never ceases to amaze.", objectives = "Kill 6 Twilight Hunters at Wolf's Run in Mount Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25256] = { id = 25256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sent for Help", description = "You, {race}, stop a minute.\n\nMy boss Spiketooth sent me to look for help and supplies.  You don't appear to be a merchant, but you can probably still help him out.  He's just to the southeast of here, next to the crashed cart.  Oh, and tell him I sent you... I want to make sure that he knows I'm not just slacking off over here.", completion = "Vek'nag sent you?  Without telling you that I need wagon wheels, nails, and rations?  That idiot.", objectives = "Report to Spiketooth at Deadeye Shore in Durotar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25257] = { id = 25257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ghislania", description = "I own a couple gladiators that I put into competitions around Kalimdor.  You can see most of them chained up around here... we were lucky to rein these ones in after the cart broke down.\n\nGhislania, that naga over there... she's lost her last three fights.  She could use a tune-up, or maybe just a little bit of thrashing.  Go challenge her, I'll bet even YOU are stronger than she is.", completion = "I watched you fight out there.  How long you been a {class}?\n\nYou're alright, kid.", objectives = "Defeat Ghislania in combat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25258] = { id = 25258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Griswold Hanniston", description = "Griswold, chained up over there on the cliffs, is my newest gladiator.  We found him just south of here, sniffing around with Northwatch soldiers.  I had my men nab him up, and now he works for me.\n\nHe looks tough enough, but he hasn't really been battle-tested yet.  Go pick a fight with him so I can see if he's worth keeping around.", completion = "I'm at a crossroads now, {name}... you defeated him easily in combat, but then again, I did get him for free, and he's pretty cheap to feed.  Maybe we'll keep him around for a bit.", objectives = "Defeat Griswold Hanniston in combat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25259] = { id = 25259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gaur Icehorn", description = "I wouldn't normally keep a taunka as a captive, due to their close relationship with the Horde... but this one is a traitor, and a criminal to boot.  Exiled by his own tribe, he canoed down to Azshara and was found stealing supplies from Valormok.  He would have been put to the axe had I not been standing by, wallet in hand.\n\nGaur is my winningest gladiator, {class}.  I'll bet you a fist full of silver that you can't beat him.", completion = "Fine, here's the money... but you'd better make yourself scarce before I reconsider my policy on keeping Horde slaves.", objectives = "Defeat Gaur Icehorn in combat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25260] = { id = 25260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fizzled", description = "The flood to the southwest wiped out one of the few Burning Blade camps that still pockmark Durotar.  This one was led by a goblin named Fizzle Darkclaw, and believe me, we're better off without him.\n\nDarkclaw, however, did possess an orb that the Horde is interested in procuring.  Who knows why... I leave that to the warlocks.  All I know is that I need that orb.", progress = "Run into any trouble on the way?", completion = "I ask for an orb, and you bring half of the goblin's arm with you?  I like the way you work.\n\nTell you what... you've already given me a hand.  Allow me to return the favor.", objectives = "Obtain Fizzle's Orb from Fizzle Darkclaw in Thunder Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25261] = { id = 25261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Margoz", description = "One of our more useful shaman, Margoz, knows more of the Burning Blade's corruption.  He speaks of a cave called Skull Rock in the mountains, just outside Orgrimmar, that shelters a large band of Burning Blade cultists.\n\nBefore you go to Skull Rock, speak with Margoz.  He is wise and his council is valued.\n\nHe is camped to the southeast, between the coast and Drygulch Ravine.\n\nFollow his advice, but whatever Margoz says, {name}, I still want you to crush those cultists!", completion = "Welcome, {name}.  Word reached me of your coming, and of your exploits in Durotar.\n\nYou are a {class} of growing skill and renown.\n\nStay on the pure path, and your future will be great indeed.", objectives = "Speak with Margoz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25262] = { id = 25262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skull Rock", description = "{name}.  The Burning Blade has infested the cave east of Orgrimmar known as Skull Rock.  Inside that cave they perform vile rituals, and burn their own flesh with Searing Collars.\n\nBy wearing these collars, I believe the cultists attune themselves to demonic power.  But to confirm this, I must have a collection of the collars to study.\n\nGo to Skull Rock and gather Searing Collars from the cultists you find there.  Bring them to me, and I will uncover their secrets.", progress = "Have you yet entered Skull Rock, {name}?  Do you have the Searing Collars?", completion = "Good.  Hiding within these collars is the secret behind the Burning Blade.  And I will uncover that secret...", objectives = "Gather 6 Searing Collars from the cultists in Skull Rock.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25263] = { id = 25263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arnak Fireblade", description = "The Searing Collars you brought me are powerful demonic implements.  Divining their origin is, I'm afraid, beyond my skills as a shaman.  We will need a warlock to study them.\n\nTake a searing collar to Arnak Fireblade.  Although he is a skilled warlock, he professes to use his powers to thwart demons, and claims his research in the occult is benign.  Be that true or false, we may need his aid against the demonic cult in Durotar.\n\nYou may find Arnak in Orgrimmar in the Cleft of Shadow.", progress = "My most humble greetings, {class}.  How might I help my {race} brother today?", completion = "Ah, and where did you get this?  Good Margoz sent you to me, did he?\n\nWell, let me take a closer look...", objectives = "Bring an Example Collar to Arnak Fireblade in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25264] = { id = 25264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ak'Zeloth", description = "Since the last great war when the Burning Legion was defeated, I have searched for sources of demonic corruption in orc society.  The collar you brought me confirms my fears.\n\nIt belongs to the Burning Blade.\n\nYour role in this tale is nearly complete, {name}.  Go to Far Watch Post, on the border of the Barrens to the west, and speak with my assistant, Ak'Zeloth.  Pass on to him this information.", completion = "This is not news to me.  While I appreciate your efforts, the Burning Blade will have to wait.  We have other matters to which we must attend.", objectives = "Speak with Ak'Zeloth at Far Watch Post in the Northern Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25265] = { id = 25265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victory!", description = "We just can't thank you enough for all that you've done. Now we can all get off of this island before it kills us!\n\nThrall is going to want to speak with you first, {name}. I'll rocket you over there.\n\nSee you on the ship!", completion = "Lok'tar! Victory, {name}!", objectives = "Speak with Thrall at the Gallywix Docks on the Lost Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25266] = { id = 25266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Emissary", description = "The goblins and the Horde have accomplished too much together to part ways now, {class}. I intend for the Bilgewater Cartel to become part of the Horde.\n\nI have something that I want you to deliver to the new warchief. Give this package to my Darkspear friend on the dock at Bladefist Bay in Durotar. She will help you to get into Orgrimmar safely.\n\nSpeak with Sassy Hardwrench on the ship when you are ready to set sail.\n\nUntil we meet again. Aka'Magosh, a blessing on you and yours, {name}!", progress = "What possible business could you have in Orgrimmar, {race}?", completion = "<The orc continues on in hushed tones.>\n\nI know who sent you. Did he give you something to deliver to me?", objectives = "Deliver the Sealed Package to the Darkspear Loyalist on the docks at Bladefist Bay in Durotar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25267] = { id = 25267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Message for Saurfang", description = "<The Darkspear loyalist opens the package and reads the letter within. As she finishes the note from Thrall, a hint of a fanged smile appears on her face.>\n\nYa should take dis directly to Saurfang inside Orgrimmar. Be sure ta let him know dat de package be from Thrall.\n\nTake me raptor. Hurry, little one, dere be no time ta waste!", progress = "What is this, {race}? Your kind are not allowed inside Grommash Hold.\n\nLeave before I have to teach you your place.", completion = "Thrall had you deliver this?\n\n<The Warchief takes a step back, visibly shaken.>\n\nI understand the meaning of this all too well, {race}.\n\n\n\nThis smelly thing was caught unattended in the city and seems to recognize you.\n\nI have already put others of your kind to work in Azshara. Take it with you when you leave.\n\nFrom this day forward, you and your Bilgewater Cartel will serve the Horde!", objectives = "Deliver the SI:7 Emblem to High Overlord Saurfang at Grommash Hold in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25268] = { id = 25268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Voice of Goldrinn", description = "Southwest of here lies the shrine of Goldrinn, a memorial erected in honor of the ancient wolf spirit and his contribution during the War of the Ancients.\n\nOur new worgen allies have been drawn to the memory of the wolf god - go figure! - and were in the process of cleaning up the shrine.\n\nI haven't heard anything from my contact, Ian Duran, in days. Can you fly down there and find him? I've got a bad feeling that Goldrinn's shrine is in trouble...", completion = "You're here to rescue me, {class}? Thank you!\n\nNo, no, don't worry about the cage for now. My life isn't important. We've got to save the shrine, first.", objectives = "Locate Ian Duran near the Shrine of Goldrinn in Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25269] = { id = 25269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Voice of Lo'Gosh", description = "Have you heard of Lo'Gosh, the wolf ancient? In the Alliance tongue, he is known as \"Goldrinn.\"\n\nI don't need to tell you how important the wolf god has been to the Horde - his tenacity under adversity has been an inspiration to all of our disparate races.\n\nSouthwest of here, down in the valley, lies a shrine to Goldrinn. My friend Takrik Ragehowl was refurbishing the shrine when I stopped hearing from him. I fear the worst.\n\nPlease find Takrik and make sure the shrine is okay!", completion = "Lok'tar, {class}! Don't worry about this cage - these animals will come to fear me before long.\n\nMy first priority is to clear this filth away from my beloved shrine.", objectives = "Locate Takrik Ragehowl near the Shrine of Goldrinn in Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25270] = { id = 25270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Howling Mad", description = "The shrine has been taken, {name}. We need the tenacity of Lo'Gosh now more than ever.\n\nThese defilers - the lice-ridden wolf-men running rampant over the shrine - dishonor the memory of the wolf god. They arrived with the Twilight's Hammer, howling with their own twisted religion. They seek to corrupt noble Lo'Gosh to fit their own warped pantheon.\n\nKill them! Kill them and bring me the tools of their worship, a kind of polluted incense. I must understand what they want with the shrine...", progress = "These animals were once men, but they've turned into mindless beasts under the influence of the Twilight's hammer. Do not hesitate to slay them all.", completion = "<Takrik examines the incense.>\n\nDisgusting. This is like the incense we burn when we wish to commune with the spirits... but it's... befouled.", objectives = "Acquire 6 Polluted Incense.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25271] = { id = 25271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goldrinn's Ferocity", description = "The beasts you see here, they're no longer my brothers from Gilneas. They've been corrupted by some kind of madness, and they've taken over the shrine.\n\nThey came when the Twilight's Hammer arrived in Hyjal, and they howl the name of some blasphemous mockery of our beloved Goldrinn. Forget about me - destroy these vandals before they continue to defile the shrine.\n\nAs you destroy them, look for the incense they carry and bring me some samples.", progress = "Worgen like myself were drawn to the story of Goldrinn, his strength and wisdom. But these vandals - they worship a different aspect of the wolf god entirely.", completion = "<Ian examines the incense.>\n\nAs I suspected. These reagents bear the marks of the Twilight's Hammer. And here, the name \"Lycanthoth.\" I believe these are used in a summoning ritual...", objectives = "Acquire 6 Polluted Incense.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25272] = { id = 25272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lycanthoth the Corruptor", description = "The actions of these feral dogs are beginning to make sense. The Twilight's Hammer fears the power of the ancients. They do not want Lo'Gosh to return.\n\nSo they've summoned their own wolf god - a perversion of what once was. \"Lycanthoth,\" the corruptor.\n\n{name}, Lycanthoth is but a shadow of Lo'Gosh's power, but the beast must be destroyed so that the true ancient can return. Take this incense, and burn it in the Maw of Lycanthoth east of here. Slay the monstrosity and free the spirit of Lo'Gosh!", progress = "Your bravery is an inspiration to others, {class}. Tell me your name.", completion = "You were brave to face down Lycanthoth, {name}. Like myself, he was a primal force of nature... but his origins were from a darker place.\n\nThose who birthed that beast reached deep into the blackness, channeling powers never intended for this world.\n\nCome, {class}. Climb onto my back, and let us show these beasts the true face of ferocity!", objectives = "Use Lycanthoth's Incense within the Maw of Lycanthoth in Hyjal to summon and kill Lycanthoth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25273] = { id = 25273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lycanthoth the Corruptor", description = "I think I understand what's happening here. The Twilight's Hammer fears that the ancients may someday rise up to oppose them. They'll do anything to stop the return of Goldrinn.\n\nThis \"Lycanthoth\" is a twisted version of our beloved wolf god, summoned by the Twilight's Hammer to replace him.\n\nBah! It is but a shadow of Goldrinn's power. {name}, kill this beast so that the true ancient can return. Take this incense and burn it in the Maw of Lycanthoth east of here. Slay that beast and free Goldrinn!", progress = "Your bravery is an inspiration to others, {class}. Tell me your name.", completion = "You were brave to face down Lycanthoth, {name}. Like myself, he was a primal force of nature... but his origins were from a darker place.\n\nThose who birthed that beast reached deep into the blackness, channeling powers never intended for this world.\n\nCome, {class}. Climb onto my back, and let us show these beasts the true face of ferocity!", objectives = "Use Lycanthoth's Incense within the Maw of Lycanthoth in Hyjal to summon and kill Lycanthoth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25274] = { id = 25274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signed in Blood", description = "You're here at last, {name}.  Just in time as well.\n\nNews of Ragnaros' emergence has spurred a large wave of recruits to seek membership in the Twilight's Hammer.\n\nIf you're to infiltrate the cult, the time is now.  We will need recruitment papers -- signed in blood by a referring Twilight member.  Lure one of the new recruits away from the group and hit them with this blackjack.\n\nIf you're lucky, you'll be able to steal his recruitment papers.  Bring them back to me and we'll do our best to alter them.", progress = "Did you get the papers?", completion = "Excellent.  I'll do my best to alter these documents.", objectives = "Lure a Twilight Recruit away from the group and take his Twilight Recruitment Papers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25275] = { id = 25275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to the Labor Captain", description = "Your people are working on the terraforming of Azshara. The land will be remade in the image of the Horde so that all will know that Kalimdor belongs to us!\n\nGo north through the city. On the far side of the Valley of Honor you will find the Orgrimmar Rear Gate. Report to Labor Captain Grabbit outside the gates.\n\nFor the Horde!!!", completion = "{name}? The {name}?!\n\n\n\nThe rumors are already flying about you. I don't know if I should be thankful or frightened that you're here. At least we don't have any volcanoes in Azshara!\n\nHonestly, I can't believe you're showing your face here... Trade Prince Gallywix has setup shop atop the mountain!", objectives = "Report to Labor Captain Grabbit at the Orgrimmar Rear Gate in Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25276] = { id = 25276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your New Identity", description = "There.  Not my best work, but certainly not my worst.  You will be known as \"{name}damus\" among the cultists.\n\nThese papers will bump you ahead of the other recruits and allow you to speak directly to the Twilight instructors.\n\nGo to the proving grounds and show these to Condenna the Pitiless.  She's separating the wheat from the chaff.\n\nShow her what you're made of.", progress = "You will address me with the respect I am due, recruit.", completion = "Yshkaldamus?  Let us hope your parents brought you into this world with more than just a ridiculous name.", objectives = "Speak to Condenna the Pitiless at the Training Grounds in Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25277] = { id = 25277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleaning House", description = "We are well on our way to returning the shrine to its former glory, {name}. But there is some housecleaning to take care of. On the other side of this meadow, some ogre squatters are setting up camp, led by a thick-headed chunk of ugly by the name of Gar'gol.\n\nKill Gar'gol's minions and see if we can't send him packing.", progress = "How goes the ogre hunting?", completion = "Hah! So you really sent some heads rolling, did you?\n\nIt was said during the War of the Ancients that Lo'Gosh fought demons for ten days solid. Hopefully you weren't fighting that long...", objectives = "Kill any combination of 8 Hovel Brutes or Hovel Shadowcasters within Gar'gol's Hovel in Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25278] = { id = 25278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleaning House", description = "Thanks to your efforts, we may soon be able to return this shrine to its former glory. But first we've got to secure this valley. South of here, a group of ogres led by Gar'gol has set up camp in a stinking hovel.\n\nI wouldn't characterize Gar'gol as a 'threat' so much as an enormous fleshy obstacle thrown into our path to distract us from the real danger. Nonetheless, he and his goons will have to be dealt with.\n\nKill Gar'gol's minions in Goldrinn's name!", completion = "You really cleared that place out, didn't you? Well done!\n\nThe night elves once told me a story about how Goldrinn fought and killed a dreadlord, even as three others clung to his flanks, burning his flesh. I wonder if you or I will ever have the strength to do the same?", objectives = "Kill any combination of 8 Hovel Brutes or Hovel Shadowcasters within Gar'gol's Hovel in Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25279] = { id = 25279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shrine Reclaimed", description = "Yes, {name}. I am Goldrinn, the one called \"Lo'Gosh\" in your tongue. Your persistence in the face of fear has unbound me from twilight's grasp.\n\nMy shrine has been purified, and my worshippers have returned to their rightful place at my right paw.\n\nReturn to Takrik and continue your work here in Hyjal. I will have need of you again soon.", completion = "{name}, it was incredible! For a fleeting moment I saw Lo'Gosh through the trees - a creature of both fury and light. My cage collapsed and the vandals melted like wax under the kiss of his claws, their screams and howls echoing through the valley... Was that your work?", objectives = "Return to Takrik Ragehowl at the reclaimed Shrine of Goldrinn in Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25280] = { id = 25280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shrine Reclaimed", description = "Yes {name}, I am Goldrinn. Your persistence in the face of fear has unbound me from twilight's grasp.\n\nMy shrine has been purified, and my worshippers have returned to their rightful place at my right paw.\n\nReturn to Ian and continue your work here in Hyjal. I will have need of you again soon.", completion = "{name}, it was astounding! Goldrinn himself appeared to free us, his white fur bright like the summer moon. Our cages collapsed and the vandals melted like wax under the kiss of his claws. He was beautiful, {name}. Beautiful!", objectives = "Return to Ian Duran at the reclaimed Shrine of Goldrinn in Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25281] = { id = 25281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pay It Forward", description = "You are now able to move about this realm more freely and without fear of drowning.\n\nThis is where our work begins.\n\nFirst, you have many allies nearby who are drowning as we speak. As I saved you, you must save them.\n\nI have enchanted the shell you brought me. Use it to rescue your friends.\n\nHurry now!", progress = "Were you able to rescue the soldiers, {race}?\n\nWe will perish without their help...", completion = "While you were away, I was able to revive some of the fallen soldiers.\n\nWe'll need every hand if we are to survive here.", objectives = "Use the Enchanted Conch Shell to rescue 6 Drowning Soldiers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25282] = { id = 25282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signs Of The Times", description = "We've got to do something to reduce interest in this doomsday cult, but I'm hesitant to take much action until we know more about who is behind this group.\n\nI've had my men place markers around heavily traveled areas of the city. Take these posters and set them up where you see the markers. They won't discourage the most determined of seekers, but it's a first step in exposing this cult. The king already has enough enemies without his own people turning against him.", completion = "Well done, {name}. Now we must focus our efforts on discovering more about this cult and freeing the people they've conned into joining.", objectives = "Set up 5 Warning Posters in the Trade District, Cathedral Square, Old Town, or Mage Quarter of Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25283] = { id = 25283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prepping the Speech", description = "High Tinker Mekkatorque asked me to write a speech that he could give before the battle starts, but I can't tell which draft is good and which ones just stink.\n\nCould you try some of them out on some of the local gnome residents?  This device creates an image of Mekkatorque saying a few lines from each of my speech drafts.\n\nLet me know which one works, okay?", objectives = "Use the Gnomish Playback Device in front of Ozzie Togglevolt north of Kharanos, Milli Featherwhistle at Steelgrill Depot and Tog Rustsprocket outside the Kharanos Inn. Return to Toby Ziegear when all the speeches have been given.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25284] = { id = 25284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feeding the Fear", description = "Our resources are limited, {class}, but that doesn't mean we can't make some trouble down below. Use the ropes here to sneak down the hillside, then slay the human prison wardens.\n\nKilling a couple scrawny guards won't turn the tide of battle, but  imagine the fear and chaos we'll reap as the humans discover the mutilated bodies...\n\n<Holgom grins a yellowed grin, his eyes glinting.>", completion = "Good, good. It'll take them many sleepless nights to figure out where we came from and where we disappeared to after the kills...", objectives = "Kill 5 Tower Wardens. Use the ropes beside Holgom to quickly move in and out of Honor's Stand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25285] = { id = 25285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In and Out", description = "We've gotta get these new mechano-tanks ready for the assault.  You ready to help test these bad boys out?!  Of course you are!\n\nFirst, we need to make sure that once you're in, you can get out.  In battle, if you think your tank is going to explode, get out!  I've seen many a gnome stay in 'til the bitter end... the tank blows up, and them along with it.\n\nWell, I've upgraded this tank with an ejection seat.  Try it out for me, will ya?", objectives = "Test out the ejection system in the Ejector Mechano-Tank.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25286] = { id = 25286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Words for Delivery", description = "Here we go.  This is the speech, {name}!\n\nIt has everything to be a great battle starter: It's inspirational, has eloquent language and speaks directly to gnomes.  Never has a finer speech been written!\n\nTurn this in to Captain Tread Sparknozzle and get some transportation to High Tinker Mekkatorque!", objectives = "Give the speech to Captain Tread Sparknozzle at Steelgrill Depot.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25287] = { id = 25287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Words for Delivery", description = "All right, soldier. Time to prove your worth!\n\nTake the speech and board the flying machine \"Thunderflash\".  It's the fastest ship to High Tinker Mekkatorque and this speech is the only thing he's waiting on before starting Operation: Gnomeregan.\n\nGo! Now!", objectives = "Ride 'Thunderflash' from Steelgrill Depot to High Tinker Mekkatorque and deliver Toby's speech.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25288] = { id = 25288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infiltrating The Cult", description = "The streets of Orgrimmar are wild with rumors about the cult's origins and practices. There's only one way to know the truth about this group, {name}. You're going to join them.\n\nApproach one of the Doomsayers in the Drag and tell them you wish to join their group. With any luck, they will give you instructions to introduce yourself to one of the group's leaders and tell you where the group is hiding. Don any clothing given to you by the doomsayer; you'll need it to gain entry to the group's hideout.", completion = "Welcome, friend. We are honored that you have decided to embrace the truth and join us. Come, there will be more time to talk later and you have much to learn.", objectives = "Go to Orgrimmar's Drag and speak to a Doomsayer or take a robe from the crate near a Doomsayer to join the cult, then put on your Recruit's Robe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25289] = { id = 25289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Step Forward...", description = "With the ejection system working, I think we're ready to test out movement.  This tank has an extra special feature: Automatic Evasive Maneuvers!\n\nI want you to check out the servos on the left leg, the right leg and the Automatic Evasive Maneuver system.\n\nThis is easy stuff, so it shouldn't take too long.", objectives = "Test the Scuttling Mechano-Tank's maneuverability.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25290] = { id = 25290, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infiltrating the Cult", description = "It's getting difficult to keep the cultists out of the public eye and rumors are spreading across the city. I want you to join the cult and learn as much as you can.\n\nApproach one of the doomsayers in Old Town and tell them you wish to join their group. The doomsayer will likely give you clothing and instructions to meet with other cultists in one of the group's hideouts. Follow those instructions, {name}. It's the only way to gain their confidence.", completion = "Welcome, friend. We are honored that you have decided to embrace the truth and join us. Come, there will be more time to talk later and you have much to learn.", objectives = "Go to Stormwind's Old Town and either speak to a Doomsayer or take a robe from the crate near a Doomsayer to join the doomsday cult, then equip the Doomsday Recruit's Robe you receive.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25291] = { id = 25291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Training", description = "You've proven you're worthy of at least participating in our most basic training.\n\nYou'll find one of our settlements east of here.  Speak to instructor Mylva there.", completion = "You think you're ready for the next step then, Yshkaldamus?\n\nLet's see what you're capable of.", objectives = "Speak to Instructor Mylva in Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25292] = { id = 25292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Next of Kin", description = "<Nato pulls you aside and speaks in a whisper.>\n\n{name}, I have removed the bullet from Gann's chest, but the bubbles in his blood tell me all I need to know. His lungs are punctured, and the wound grows septic. He is not long for this world.\n\nTake this. It's the bullet that killed him. His family will want to know what became of their youngest warrior.\n\nSeek out Alto Stonespire. He is posted in Dustwallow Marsh. Go northeast, and follow the roads to Brackenwall Village.", progress = "Hello, {class}. You look to be caked in dust instead of mud. I take it you've ventured here from the Barrens?", completion = "<Alto clenches the bullet in his palm as you tell your story.>\n\nGann? Dead? I ... I should've known. His temper... his recklessness. I knew someday it would get the better of him.\n\nBut it sounds as though you've already gifted him with vengeance. Thank you, {name}!\n\nTurn your attention now to Dustwallow. If the Alliance finishes their cursed road through here, all your victories in the Barrens may have been for nothing.", objectives = "Take the Dwarven Slug to Alto Stonespire at Brackenwall Village in Dustwallow Marsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25293] = { id = 25293, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing", description = "Aside from the disturbances and the paranoia spread by the cult, we've been inundated with reports of missing people. Mothers, fathers, brothers, and sisters have seemingly disappeared, but I have a feeling that they can be found in one of the cult's compounds outside the city. If I give you the names of some of the missing people, would you try to locate them in the cultist camp at the Jaggedswine Farm south of Orgrimmar? To blend in, you'll need to get a robe from one of the doomsayers in the Drag.", completion = "So you found them? Why did the missing men and women not return with you?\n\n<You tell the blood guard about the responses you received.>\n\nWe cannot compel them to change their minds and return to their families. I will let the families know that the relatives have been found and that they are safe. After this cult is broken up, they will likely return to their normal lives.", objectives = "While wearing your Cult Disguise, speak to Cultist Kagarn, Cultist Agtar, Cultist Tokka, and Cultist Rokaga at the Jaggedswine Farm in Durotar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25294] = { id = 25294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Walking the Dog", description = "Hmmmphh.... it seems they'll let anyone in these days.\n\nVery well.  You doubtlessly became acquainted with Smolderos in the proving grounds.\n\nWell, I've been entrusted with the care of one of his pups.  Quite the little terror -- if he grows up to be anything like his father he shall serve our cause well.\n\nCollect meat from the basilisks around the area and feed them to him.", completion = "Excellent.  This little pup will grow to be strong and merciless like his father.", objectives = "Collect and feed 5 pieces of Charred Basilisk Meat to the Spawn of Smolderos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25295] = { id = 25295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Press Fire", description = "Safety systems, online!  Motor functions, functioning!  Now all we need is to make sure that the guns will fire.\n\nThis shouldn't be too hard, {name}.  The mechano-tank on the hill behind us has been loaded with harmless pellets. Just fire off a couple rounds at the nearby targets and report back to me.", objectives = "Test out the Shooting Mechano-Tank weapon systems on the nearby targets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25296] = { id = 25296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gather the Intelligence", description = "It's me, {name}, Ortell!\n\nDon't look directly at the outhouse... you'll give away my position.\n\nEverything's going according to plan then?  Excellent!\n\nI'm going to need you to obtain some intelligence while you're here.  It might not seem like much to get our hands on a map or a letter, but it may mean saving a hundred lives on our side if we can anticipate our enemy's next move.", progress = "Did you get the documents, {name}?", completion = "Excellent job, {name}.  Or should I say: \"{name}\"damus?\n\nGive me a minute to read these.", objectives = "Obtain the Twilight Communique and the Hyjal Battleplans.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25297] = { id = 25297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From the Mouth of Madness", description = "I know of a draught that should jolt these gibbering former slaves back to reality. Gather some stonebloom from the rocks around Gar'gol's hovel, some bitterblossom from the shores of the nearby lake, and a darkflame ember from one of the braziers at the hovel entrance. The draught won't last long, so combine the ingredients at a twilight cauldron by the entrance to the hovel.\n\nOne sip of that draught should knock some sense into the brainwashed slaves!", progress = "<The cauldron burbles, filled with a disgusting liquid.>", completion = "<You dump out the current contents of the cauldron, instantly killing the surrounding plant life.>\n\n<The draught you brew in its place boils chunky and reeks of rotted cabbage. You turn your head aside and bottle it up.>", objectives = "Gather up Stonebloom, Bitterblossom, and a Darkflame Ember.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25298] = { id = 25298, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free Your Mind, the Rest Follows", description = "<Rio said that the draught would not remain effective for long.>\n\n<You'd better hurry into the hovel and administer it to as many Twilight Servitors as you can find.>", progress = "Did the draught work?", completion = "Excellent! Let's hope the damage wasn't permanent.\n\nJudging by the poor victims still in camp here, the Twilight's Hammer really messed with their heads.", objectives = "Speak with 8 Twilight Servitors to administer the draught and rescue them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25299] = { id = 25299, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mental Training: Speaking the Truth to Power", description = "You might think you're ready to receive the knowledge we're to impart on you.  But you are not.\n\nThink of your mind as a box inside a series of other boxes.\n\nEach step of our training will open one of those boxes, until you are ready to achieve direct communion with the elements.\n\nTake the Core of Ascension and answer all questions it asks of you, truthfully.  Failing to do so could be... fatal.", progress = "You've returned.", completion = "You've succeeded, Yshkaldamus.  You're ready for the next step.", objectives = "Use the Orb of Ascension and answer 10 answers correctly.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25300] = { id = 25300, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eye of Twilight", description = "The ogre clan across the lake is led by Gar'gol. I use the term loosely; Gar'gol has the intelligence of raw beef.\n\nSo far as I can tell, Gar'gol is taking orders from a magical instrument: \"The Eye of Twilight.\" He follows its commands unquestioningly.\n\nIf we can sabotage the eye, we can cause unimaginable havoc.\n\nGo to Gar'gol's hovel and seek out the Eye of Twilight near the entrance. Study it. Find a way to subvert it. Ah, marvelous chaos...", completion = "<You approach the Eye of Twilight. As your fingertips graze its luminescent surface, you are aware of a malignant presence peering back at you, searching your soul.>\n\n<Instinctively, you draw back.>", objectives = "Seek out the Eye of Twilight near the entrance to Gar'gol's Hovel in Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25301] = { id = 25301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mastering Puppets", description = "<During your brief communion with the Eye, you felt that its power source lay deep within the hovel. You felt the weight of a powerful tome, binding together four elements.>\n\n<Mastering the Eye will require you to search the hovel for this tome.>", completion = "<A heavy tome, bound in flesh, lies open on the table.>\n\n<The language - pictographic and scrawled in rust-colored ink - is undecipherable, but notes and translations are tucked within several pages. This must be what you're looking for.>", objectives = "Locate the Twilight Apocrypha inside of Gar'gol's Hovel in Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25302] = { id = 25302, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remnants of Battle", description = "A great battle took place here. Mixed with the naga skeletons are that of some sort of large humanoids. This might be interesting news to XXX.", sourceObjective = "Bring the Broken Shard to XXX at XXX.", sourceObjectiveStatus = "unverified-source-field" }
quests[25303] = { id = 25303, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementary!", description = "<You can't read the text, but diagrams seem to indicate that the devices around you should be activated in a set order.>\n\n<One passage of the Apocrypha has been translated to modern text:>\n\n   In the beginning was shadow eternal.\n   Hate blazed forth, and FIRE was born.\n   Wounds scabbed, and so begat EARTH.\n   Cries of anguish birthed howling WIND.\n   Wherein the skies wept seas of TEARS.\n      We live in the shadow,\n      The world we know\n   Built of rage, hurt, anguish and sorrow.", progress = "<You pour over the Apocrypha, trying to make sense of it all.>", completion = "<Flush with the energies of the captured elementals, you stand before the Twilight Apocrypha. The pages turn of their own accord.>\n\n<Suddenly, you see what the Eye sees. It is yours to command!>", objectives = "Activate the four nearby elemental crucibles in the correct order to take control of the Eye of Twilight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25304] = { id = 25304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle of Sardor", description = "Our settlement on Sardor Isle was lost to the Hatecrest naga. Overwhelmed by their numbers, we fell back to the mainland. While they coveted their newly-gained sandbar, we raised New Feathermoon on the shore and amassed an even greater army.\n\nNow, the Hatecrest will be driven back into the sea. Find our Ancient of War along the shore. He will take you to the front lines, where Tambre leads the offensive.", completion = "These foul things will be driven back into the sea. I hope you're ready.", objectives = "Speak with Tambre on Sardor Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25305] = { id = 25305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Never Look Back", description = "Our settlement on Sardor Isle was lost to the Hatecrest naga. Overwhelmed by their numbers, we fell back to the mainland. While they coveted their newly-gained sandbar, we raised New Feathermoon on the shore and amassed an even greater army.\n\nNow, the Hatecrest will be driven back into the sea. Speak with Sentinel Ranadae to join our forces at Sardor. Slay the naga, and make sure whichever foul snake they take orders from is killed as well.", objectives = "Kill 10 Hatecrest Naga and slay their leader.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25306] = { id = 25306, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You're In The Army Gnow!" }
quests[25307] = { id = 25307, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eavesdropping" }
quests[25308] = { id = 25308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeds of Discord", description = "According to the intelligence you acquired, there is major friction between the ogres and non-ogres in the cult.\n\nHigh Cultist Azennios and the ogre mage Karr'gonn are meeting at the Seat of the Chosen in an attempt to ease the conflict.\n\nThere is an outhouse like this one at the Seat of the Chosen.  Go there and put on this ogre disguise.  Find a way to kill Azennios while he's in this mission of peace.\n\nWe must exploit this division as much as we can!", progress = "Is it done yet, {name}?", completion = "Excellent job, {name}!  You've outdone yourself this time.", objectives = "Distract Karr'gonn and slay Dark Cultist Azennios at the Seat of the Chosen in Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25309] = { id = 25309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiritual Training: Mercy is for the Weak", description = "You've made it this far.  Others haven't.\n\nGo to Doom's  Vigil, just north of here.  We've rounded up all the... failures.  I want you to help take care of them.  It'll be good for your spiritual growth.\n\nIf this cold-blooded act gives you trouble, think of it as their second chance.  Should any of them manage to kill you... well, they'll take your spot.", completion = "You're on the fast-track to success.  Let us hope you don't ruin your track record with such silly notions as compassion and humaneness.\n\nCome, then.  Let us discuss your future.", objectives = "Slay 5 Failed Supplicants at Doom's Vigil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25310] = { id = 25310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Greater of Two Evils", description = "We took Darkwhisper Gorge from the demons of the Burning Legion by force.  We've held on to our territory pretty well so far, with one exception.\n\nWe recently lost the Gates of Sothann to a pit lord and his army.  We cannot allow this to stand.\n\nUse this talisman when you're near him.  You'll gain the powers of a flame ascendant temporarily.  Make it count.", completion = "Excellent work, Yshkaldamus.  We must show all would-be competitors that we are not ones to give up easily.", objectives = "Use the Talisman of Flame Ascendancy and slay Garnoth, Fist of the Legion, at the Gates of Sothann in Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25311] = { id = 25311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Territory", description = "The demons of the Burning Legion think they can just walk up here and take whatever territory they want.  Sure -- the territory was previously theirs, but that's beside the point.\n\nWe'll teach them not to cross the Twilight's Hammer.\n\nHead to the Gates of Sothann and wipe out the contingent of Horrorguards that roam the area.", completion = "Sharp as always.  You do not disappoint me.", objectives = "Slay 10 Horrorguards at the Gates of Sothann in Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25312] = { id = 25312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Duskwhisper", description = "<You force your own image into the Eye, manipulating it to give the ogres different orders. As you do so, you feel another presence within the Eye, probing you, seeking out a weakness. A distant being fumes with rage. You've made some enemies today!>\n\n<Your work here is done, and the ogres will be friendly to you. Return to Royce Duskwhisper at the Shrine of Goldrinn and let him know what you've accomplished.>", completion = "Hello, yes? What? You? Oh, you're one of the ones I sent after the Eye of Twilight, aren't you?\n\nGood work, very good. I suppose that's a valuable lesson:\n\nNever to take orders from a big purple ball.", objectives = "Return to Royce Duskwhisper at the Shrine of Goldrinn in Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25313] = { id = 25313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Defector", description = "Stay your hand!  Please, I beg you!\n\nI'm only here because of a girl.  Her words were so sweet... but now I realize the madness behind them.\n\nTake this envelope.  It has information that'll score you some points with your superiors.\n\nThe guards are distracted... I can make a run for it.  Please.  I don't want to die!", sourceObjective = "Bring the Incriminating Envelope to Elementalist Ortell at the Outhouse at the Forge of Supplication in Hyjal.Stay your hand!  Please, I beg you!\n\nI'm only here because of a girl. Her words were so sweet... but now I realize the madness behind them.\n\nTake this envelope. It has information that'll score you some points with your superiors.\n\nThe guards are distracted... I can make a run for it. Please. I don't want to die!", sourceObjectiveStatus = "unverified-source-field" }
quests[25314] = { id = 25314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speech Writing for Dummies", description = "Listen, {name}.  I found out what they're doing with Jarod Shadowsong.  He's scheduled to be sacrificed by the ogres of the Twilight's Hammer as part of this year's initiation.\n\nI heard that the initiate charged with delivering the speech ahead of the sacrifice is an ogre named Okrog, but get this: you were a close second.\n\nWe need you to deliver that speech if we're to free Jarod.  Don't worry -- I'll write you some cue cards -- just make sure Okrog has an \"accident\" as he leaves the Seat of the Chosen.", progress = "Well, {name}?", completion = "Excellent work, {name}.  Our plan's almost come together.", objectives = "Kill Okrog outside the Seat of the Chosen in Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25315] = { id = 25315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Graduation Speech", description = "You're finally ready, {name}damus.\n\nI am so proud of you and all you've accomplished.\n\nToday you will deliver a speech in front of your peers and inspire them to crush our enemies until Hyjal is nothing but a pile of ash.\n\nRemember, {name}damus.  It'll be important to read your audience's emotions and use words that best address those emotions.", progress = "Have you come to finish me off?\n\nNo... you appear to be... sane.", completion = "You.  You're clearly not with them.\n\nAn ally then?", objectives = "Use the Initiation Podium at Doom's Vigil to successfully deliver the Graduation Speech.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25316] = { id = 25316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "As Hyjal Burns", description = "{name}!  We've heard much about you and your previous accomplishments.\n\nIt is good that you've come here just as Azeroth finds itself in a time of great need.\n\nDeathwing's minions are attacking Hyjal and seek to bring the destructive Ragnaros back into our world.\n\nAronus will take you to join Malfurion's forces in Hyjal. Lend them what help you can.", completion = "<Ysera appears to be in some sort of trance.>", objectives = "Fly to Hyjal using Aronus and speak to Ysera once you're there.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25317] = { id = 25317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Protect the World Tree", description = "<Ysera's eyes look distant, as if not fully acknowledging you.>\n\nI feel it as well, {class}. Ragnaros has arrived.\n\nWe must defeat his minions before he can join them and lend them his strength.\n\nSeek Malfurion Stormrage at the Tranquil Grove, west of here, and aid his forces in any way you can.\n\nI must seek answers from within the Emerald Dream.  You must protect the World Tree until I return.", completion = "You've arrived just in time, {name}.", objectives = "Speak to Malfurion Stormrage at the Tranquil Grove in Mount Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25318] = { id = 25318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Battle Plans" }
quests[25319] = { id = 25319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War on the Twilight's Hammer", description = "Make no mistake about this, {name}.  The outcome of this war will determine the very survival of our world as we know it.\n\nThe Twilight's Hammer has become more powerful than ever with Deathwing's return.  Should they succeed in taking over the World Tree, they might strike a blow from which we will never recover.\n\nIt is time we beat back the enemy.  It is time we crushed the Twilight's Hammer.", completion = "You've done well, {name}.  But I fear the battle is far from over.", objectives = "Kill 4 Twilight Flamecallers and 10 Twilight Vanquishers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25320] = { id = 25320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captured Scout", description = "I've heard about you, {name}, and the news you brought from the south.  The battle has reached a stalemate.\n\nOne that I fear is about to be broken by the Firelord's reawakening.\n\nThat is unless we tip the scales in our favor in some way.\n\nThere is a scout that was captured by the Twilight's Hammer.  I believe she was in possession of valuable intelligence. Find her in the Twilight camp to the west.", completion = "Help has arrived at last!", objectives = "Find Scout Larandia at the Twilight Command Post in Mount Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25321] = { id = 25321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Captivity", description = "I'd been scouting behind enemy lines for nearly a day when they caught me.\n\nThis attack on our frontlines is not what it appears, {name}.\n\nI'll give you all the details, but first let's find a way to get me out of here.\n\nOnly the overseers carry keys to these cages.\n\nFrom what I recall, they're in the middle of the crater, in the thick of it.\n\nSee if you can get a key off of one of them.", progress = "The key, {name}.  Did you get it?", completion = "I am thankful, {name}.  I will deliver my findings to our people.", objectives = "Obtain a Twilight Overseer's Key at the Twilight Command Post in Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25322] = { id = 25322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fiery Inscriptions", description = "The medallion is unlike any you've seen before.  Its runes appear to glow in conjunction with the near fire elementals.\n\nPerhaps you should tell Hamuul Runetotem about this.", objectives = "Speak to Hamuul Runetotem in Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25323] = { id = 25323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flamebreaker", description = "The large elementals that besiege us are not a singular entity.\n\nThey are an amalgamation of lesser spirits bound together by the Twilight's Hammer cultists' magic.\n\nThe rebuilt flameseer's staff will give us enough power to shatter its bonds.\n\nDestroy the smaller elementals once you've broken up the more dangerous large ones.", progress = "Is it done, {name}?", completion = "Well done, {name}.  This will help us turn the tide against the enemy.", objectives = "Kill 30 Unbound Flame Spirits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25324] = { id = 25324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Prisoner of Interest", description = "The Twilight's Hammer wants to free Fandral Staghelm?\n\nMalfurion suspected his corruption ran deep... this just cements it.\n\nAt any rate we cannot allow our enemies to get their hands on such a powerful arch druid.\n\nI've a plan, {name}.  We will move the prisoner through the Emerald Dream.  It will be risky, but with all the cultists present here it might be the only way to guarantee our success.\n\nSpeak to Saynna Stormrunner inside the Barrow Dens to the northeast.", completion = "The dragon might be right.  The Twilight's Hammer has breached our security and this is our most dangerous prisoner.", objectives = "Speak to Captain Saynna Stormrunner at the Barrow Dens in Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25325] = { id = 25325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through the Dream", description = "Alysra's plan might be necessary, {name}.  I don't know how much longer we can hold off the cultists.\n\nFandral Staghelm is bound by powerful spells.  He won't be able to escape you, even inside the Emerald Dream.\n\nBeware, though, for all we know the nightmare has spread to this part of the world inside the dream.\n\nTake Fandral to the surface and hand him to Alysra.  Let us hope he's more secure in Moonglade than he is here.", progress = "Is Staghelm with you, {name}?", completion = "You did well, {name}.  I will take Fandral to Moonglade myself.\n\nHis prison will be far enough from the battlefront there.", objectives = "Deliver Arch Druid Fandral Staghelm to Alysra at the entrance of the Barrow Dens in Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25326] = { id = 25326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Block Their Retreat" }
quests[25327] = { id = 25327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Awakening" }
quests[25328] = { id = 25328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gar'gol's Gotta Go", description = "<Kristoff cranes his neck, trying to look you in the eye.>\n\nListen, you gotta get me outta here. They're either going to eat me or turn me over to the Twilight's Hammer. Maybe both.\n\nThey've padlocked me in, and Gar'gol keeps the key in his personal treasure chest. Kill Gar'gol if you have to - but get that key!\n\n<Kristoff flails his limbs, helplessly.>", progress = "Key? Now? Please?", completion = "<Kristoff reaches down to snatch the key.>\n\nIt's about time!\n\n<He squirms in his bonds, trying to reach the padlock behind his back.>\n\n...Can I get a little help here?", objectives = "Get the Rusted Skull Key from Gar'gol's Personal Treasure Chest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25329] = { id = 25329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Might of the Stonemaul", description = "So the Twilight's Hammer thinks it can just raise its own army of ogres here? In the middle of Horde territory? \n\nWe'll see about that.\n\nOgres only respect one thing: strength. I want you to lead the assault on Cho'gall's sermon, {name}. Throw wide the doors of Dire Maul, leap into the arena, and cut down his attendants.", completion = "We've done it! Cho'gall himself has been utterly humiliated by you. His minions are dead, the Gordok are scattered, and now all will know the might of the Horde! Lok'tar, {name}. You've more than earned your reward.", objectives = "Disrupt Cho'Gall's Twilight Sermon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25330] = { id = 25330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waste of Flesh", description = "Look at these fools.  Half of them won't even make it past this trial.\n\nThey are not worthy of ascending into our inner circles.  But perhaps... perhaps they are worthy of menial service.\n\nTake this gem and utilize its power to save some of the less competent supplicants.  Those who have no chance of succeeding.  Those already on fire, preferably.", progress = "Did you find suitable servants for me, Growlnardamus?", completion = "Excellent work, Yshkaldamus.  I'm having the servants you chose for me briefed on their new duties.", objectives = "Use the Frostgale Crystal to extinguish the flames on 4 Immolated Supplicants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25331] = { id = 25331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grandma's Cat", description = "Right!  About the evacuation, dear.\n\nI just cannot leave without my cat.  He's an adorable orange tabby.\n\nChance's favorite spot to play is a broken down cart near an arbor northeast of here.\n\nBring him here and we'll be on our way.", objectives = "Grandma Wahl at the Wahl cottage wants you to retrieve Chance the Cat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25332] = { id = 25332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Me Outta Here!", description = "<You reach up to unfasten Kristoff's bonds.>\n\nGood! Make a break for the exit, and I'll follow.\n\nIf we get separated, check back here to make sure I haven't been recaptured.", completion = "Kristoff, Kristoff... Oh yes, I remember now. I recall sending him on what amounted to a suicide mission.\n\nHe survived? I suppose that means he failed.\n\nStill, you deserve at least some coin for the trouble.", objectives = "Escort Kristoff out of Gar'gol's Hovel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25333] = { id = 25333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Might of the Sentinels", description = "The Twilight's Hammer? Here?\n\nThis is far more serious than I expected. We've got to put a stop to this. I don't know if I'm ready to lead such an offensive, but I'm not about to let my fears get in the way of what needs to be done!\n\nI will rally our forces from Feathermoon Stronghold. Head to Dire Maul, make your way to the arena, and disrupt Cho'gall's activities; we will launch our attack during the confusion.", completion = "Welcome back from the battle! The Twilight's Hammer have been disgraced in the eyes of the Gordunni, and driven from Feralas.\n\nWe've shown the glory of the Alliance in full force today! Be proud!", objectives = "Disrupt Cho'Gall's Twilight Sermon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25334] = { id = 25334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Looming Threat", description = "Can ya feel how angry the elements be? They be wantin' to attack us and consume us even as we just arrive. We need ta calm dem, but that kinda wisdom only comes from knowin' what's riling them up in da first place.\n\nCome sit with me by da fire. Let yaself get lost in da flames... let ya spirit peer into the true threat.", progress = "Lose yaself in the dancin' flames. Come with me, deeper into Vashj'ir, so that we be knowin' the face of our enemy.", completion = "We'd all suspected da naga, but I knew nothin' of the Twilight Cult bein' beneath the waves. Somehow dey are corruptin' and pervertin' the elements, makin' demselves into dese horrors.\n\nWe goin' ta have to be fightin' both of dese threats to stand a chance of bringin' peace ta Vashj'ir. We don't have da men ta do that yet.\n\nCome, {class}, we got much ta do.", objectives = "Speak to Farseer Gadra to enter your Spirit Trance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25335] = { id = 25335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Natural Materials", description = "I will need certain materials to complete my endeavor... You may do this alongside the other tasks I will give you.\n\nI'll need a splintered log from a treant of Feralas. Encrusted minerals, these can be found on the mountain giants and faerie dragons to the west. Also, find me some resilient sinew from the owlbeasts of the Hinterlands or hippogryphs of Feralas. Finally, I'll need a large amount of metallic fragments from any of these creatures I mentioned.", objectives = "Bring 2 Splintered Logs, 6 Encrusted Minerals, 20 pieces of Resilient Sinew, and 40 Metallic Fragments to Witch Doctor Uzer'i in Camp Mojache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25336] = { id = 25336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Testing the Vessel", description = "Master Uzer'i's taught me in the ways of making spirit weapons of great power. I'll help you set on the path to make some, and you'll give me the chance to practice my craft.\n\nThis vessel can shrink and trap a defeated creature inside of it. We'll need the muisek of beasts first; ironfur bears and longtooth wolves. Kill them, and use the muisek vessel to shrink and capture them before their spirits can escape.", progress = "Did you get the beast muisek?", completion = "As my master told me...\n\nUpon a violent death, the muisek of a creature may escape and seek revenge. Shrinking the creatures, as you did, {name}, prevents the muisek from escaping. Now we may use it as we please!", objectives = "Kill 10 Ironfur Bears or Longtooth Runners, and use the Beast Muisek Vessel to shrink and capture the fallen beasts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25337] = { id = 25337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hippogryph Muisek", description = "The next step is hippogryphs.\n\nAs Master Uzer'i always said, hippogryphs have been loyal companions to the night elves for many years, an' their spirits are loyal and steadfast.\n\nI don't think they'll miss a few, and I don't care if they do. We need the muisek of 10 frayfeather hippogyphs in the wilderness to the south.", progress = "Were you able to capture the hippogryphs?", completion = "Master always said \"after killing an animal, if we allowed the muisek to escape, it may take the form of an even greater creature.\" This is dangerous stuff. Thanks for helping me with my studies.", objectives = "Kill 10 Frayfeather Hippogryphs of any type, then use the Muisek Vessel to shrink and capture them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25338] = { id = 25338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treant Muisek", description = "The wandering forest walkers that can be found meandering through the forest are our next target, {name}. Night elves have enlisted treants as allies to fight against the horde. Their movement may be slow, but their role as protectors is undeniable.\n\nSoon we will be able to use this power for our own benefit.\n\nFind three wandering forest walkers; kill them, and use the muisek vessel to shrink and capture them.", progress = "Were you able to capture the wandering forest walkers?", completion = "Thank you, {name}. This is my first time working with treant muisek...", objectives = "Kill 3 Wandering Forest Walkers. Use the Muisek Vessel to shrink and capture the fallen Treants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25339] = { id = 25339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeance on the Northspring", description = "In my day, I was a seasoned hunter. There wasn't any creature around that I feared. Until...\n\nI was out in the forest, sharpening my blade after a tough battle, when I was ambushed. Harpies surrounded me, and I barely managed to drag myself to safety.\n\nEven now, I can still hear their cries echoing...\n\nI was never the same after that. But the hate boils inside of me -- I must get even, after all these years.\n\nThe Northspring harpies can be found to the west of here. {name}, get my revenge.", completion = "Thank you, {name}. You have put an old tauren's mind at peace.", objectives = "Kill 6 Northspring Harpies and 6 Northspring Windcallers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25340] = { id = 25340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Heart", description = "Edana Hatetalon is the queen of the Northspring harpies that reside in the ruins to the west. She is pure evil; I have heard that her heart is one of crystal. She is void of any emotion aside from the hate she feels towards all others. You must face Edana and bring me back her dark heart.\n\nI have heard of a horn that harpies carry -- blowing it by the Hatetalon stones, in the northern part of the ruins, will summon the queen.\n\nImagine her surprise when it is not her kin calling her, but her death.", progress = "The hate that Edana spreads across the land must be stopped.", completion = "Now I know that Edana is truly dead. This heart, I will keep it in memory of what you did here for me, {name}. Thank you.", objectives = "Slay Edana Hatetalon and obtain Edana's Dark Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25341] = { id = 25341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gordunni Orb", description = "While you're down there cracking skulls...\n\nI've gotten reports that make me think these ogres may be more than the usual lumbering threat. The Warlocks among them have been seen carrying orbs, possibly items of empowerment.\n\nIt would be easy to dismiss them as crude trinkets, but I need to make sure we're not surprised. Bring me back one of these orbs.", progress = "Do you have the orb?", completion = "Well done. Let me have a look at this.", objectives = "Collect a Gordunni Orb from a Gordunni Warlock.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25342] = { id = 25342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talk to Swar'jan", description = "We're lucky and unlucky here, grunt. Lucky that I had you bother to bring this back, and unlucky that my suspicions turned out to hold water. This thing's full of corrupted stench.\n\nIt's far too new to be something fished out of the ruins, either. Someone is supplying these ogres, and we need to know who before this becomes a situation.\n\nGet that filthy thing upstairs to Swar'jan, the warlock on top of the guard tower. He's good for a few ideas; I'd listen to his suggestions, if I were you.", progress = "Yes?", completion = "What've you got for me here? You said the Gordunni had this?\n\nDisgusting...", objectives = "Deliver the Gordunni Orb to Swar'jan in Stonemaul Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25343] = { id = 25343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Master's Plan", description = "You're fitting in well here, {name}, but there is more to us than daily chores and spreading the message. I'm sure you heard a little bit about it when you first joined.\n\nAs you know, this world is ending and the unprepared will die painful deaths.\n\nWe have been given a gift, an opportunity to become something greater and more powerful. Overseer Golbaz is preparing a ritual before the altar at the eastern end of the farm. Wait there for him, and learn more of your new brothers and sisters.", completion = "Now that you understand the master's plan, you must prepare yourself to play your part.", objectives = "Learn more about the cult's plans at the altar in the eastern part of the Jaggedswine Farm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25344] = { id = 25344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogre Abduction", description = "There's no way the Gordunni made these. They're being supplied. Someone is giving them gifts of power, and we need to find out who.\n\nThe upper-class Gordok that guard Dire Maul will know more about this. Orhan is no doubt having you thin their numbers, but I'll need one alive.\n\nTake the orb back. It's similar to a Soulstone, so I've made some...adjustments. Hold it up in front of a weakened Gordok ogre, and once you've captured him, bring it back here.", completion = "Ahh, I can feel the whelp in there. Let's get him out and ask him some questions...", objectives = "Use the Modified Soulstone to capture a Gordok ogre.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25345] = { id = 25345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faerie Dragon Muisek", description = "{name}, next I must have you capture a creature that in appearance, may look quite fragile, yet its powerful spirit is what we are truly after. The faerie dragons that I speak of have served the night elves as their allies. We must capture one so that the horde may benefit from this strength of spirit as well.\n\nHere is the muisek, {name}. Kill 8 sprite darters or sprite dragons, and capture their muisek. They may be found to the west of here.", progress = "Were you able to capture the muisek of the faerie dragons?", completion = "Thank you, {name}. Now the spiritual powers of the faerie dragon will be available to us.\n\nI hope you willing to perform another task for me.", objectives = "Kill 8 Sprite Darters or Sprite Dragons. Use the Muisek Vessel to shrink and capture the fallen Faerie Dragons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25346] = { id = 25346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mountain Giant Muisek", description = "The mountain giants left the mountains to aid the night elves when the Burning Legion appeared in the world. You will know them by their massive size and the way the ground begins to shake as you travel along their rocky terrain.\n\nI am eager to harness power of that size. Kill 7 mountain giants, then use the muisek vessel to capture their powerful muisek.", progress = "Were you able to capture the mountain giants?", completion = "Just imagine the possibilities of what we now possess, {name}. Along with the materials that you have collected, I will be able to forever trap the muisek of these creatures into whatever I wish.", objectives = "Kill 7 Mountain Giants. Use the Muisek Vessel to shrink and capture the fallen Mountain Giants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25347] = { id = 25347, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Doomsday Plan", description = "The first batch of elemental devices are ready. Your task will be to conceal them inside the city of Orgrimmar. The devices will unleash their fire elementals at the proper time. Don't worry, {name}, you'll be safely away before that happens.\n\nDo not do anything that would draw attention to yourself.\n\n<The overseer hands you a package containing several of the elemental devices. This is just the kind of proof that Blood Guard Torek was hoping you'd uncover. You should probably bring the devices to him.>", progress = "You've returned at last. I was beginning to think that you'd taken up with the cultists for good.", completion = "<You hand Blood Guard Torek the devices that the overseer gave you, explaining the cult's plans. Torek's eyes go wide.>\n\nCho'Gall is in charge of the cult? There can be no question then, this is the work of the Twilight's Hammer! You won't be the only one they've sent into the city to deploy these devices.", objectives = "Take the Elemental Devices to Blood Guard Torek in Orgrimmar's Valley of Strength.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25348] = { id = 25348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thwarting Twilight's Hammer", description = "You can't have been the only person sent into Orgrimmar to deploy those devices containing fire elementals. We have to find and disable the rest of the devices before they set their captive elementals free and burn down the city.\n\nAre you familiar enough with the devices to destroy them? You need to break them open before the fire elementals inside have had time to reach full strength. They should be easy to defeat if you open the devices early. The cultists have probably put them all over the city.", completion = "Excellent work, {name}. Twilight's Hammer will think twice before trying to turn our own people against us again. I'm sure I'm not the only one troubled by just how many citizens were taken in by their message. Times aren't exactly easy, but if you have no honor or loyalty, you have nothing.", objectives = "Break Elemental Devices to release their elementals. You must defeat 5 Raging Fire Elementals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25349] = { id = 25349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twisted Sisters", description = "I have heard of your battle against the corrupted dragons, {name}, and I thank you for your courage... but I have disturbing news.\n\nThe dryads of the forest, though allies of the Night Elves, have always passed us by in peace. But they have become cruel and twisted, attacking any who wander the eastern wilds.\n\nI fear for the safety of the refugees here, {name}. Please, put a stop to these twisted dryads.", completion = "I thank you, {name}, but the tale of your hunt troubles me. There should not be so many.\n\nThe sickness is still spreading...", objectives = "Kill 7 Corrupted Dryads.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25350] = { id = 25350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Apprentice", description = "If you have a moment, {class}...\n\nOne of the students I was teaching has gone to explore the darkmist ruins to the south by himself. I warned him that it was too dangerous, but he was too excited to listen.  I had spoken with him earlier about an amulet that is concealed within those ruins.  Now, I fear that he may have run off in search of it, because of me...\n\nEstulan has forbidden us to pursue him. If you go there, could you please look for him?", completion = "<The apprentice's body is cold. He has been dead for a while.>", objectives = "Look for the Lost Apprentice in the Darkmist Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25351] = { id = 25351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alert Our Leaders", description = "You have successfully defended Orgrimmar from the threat posed by this Twilight's Hammer cult, {name}, and without shedding the blood of our own people. Our enemy will not rest for long. I cannot imagine that Cho'Gall will accept defeat so easily.\n\nGarrosh Hellscream is a well-known hero of the Horde and he will know how to deal with this matter. Go to the Valley of Wisdom and speak to him in Grommash Hold. Tell young Hellscream that our enemies have shown themselves and we must be prepared for their return.", completion = "<The warchief listens as you tell of your investigation into the Twilight's Hammer plot to destroy Orgrimmar.>\n\nYou are a dutiful member of the Horde, {name}. You have done well in bringing this news to me. I will personally see to it that our enemies get what they deserve!", objectives = "Speak with Garrosh Hellscream at Grommash Hold in Orgrimmar's Valley of Wisdom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25352] = { id = 25352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sweeping the Shelf", description = "Wonderful work in the hovel, {name}. I prayed at the shrine while you were away, and in my visions, Goldrinn was watching you closely.\n\nBut we've been on the defensive too long: it's time to foil the Twilight's Hammer directly.\n\nFly up to the Lightning Ledge and disrupt their operation. Kill the stormcallers and the monstrosities they're preparing to unleash!", completion = "You should've seen the battle from here! Bodies were falling off of the cliff! Spectacular!", objectives = "Slay 8 Twilight Stormcallers and 5 Howling Riftdwellers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25353] = { id = 25353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lightning in a Bottle", description = "When I prayed at the shrine, Goldrinn granted me another vision. I saw you standing astride the Lightning Ledge, with lightning in your hands. Goldrinn seems to feel that this is of the utmost importance, but I don't understand what the ancient has planned...\n\n{name}, go to the Lightning Ledge. Twilight's Hammer has been running experiments with something called a \"Lightning Channel.\" Investigate these channels, then use this totem to summon the Spirit of Goldrinn and see what he has in mind...", progress = "We meet again, {class}. You carve a path of fear and confusion in your wake.", completion = "So, it is true! You indeed carry lightning in your hands.\n\nYou are the chosen one, {name}. You will be my champion, and carry my vengeance to realms where I cannot tread...", objectives = "Collect a Charged Condenser Jar from a Twilight Lightning Channel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25354] = { id = 25354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sweeping the Shelf", description = "The shrine is secure, the ogres in disarray. Enough. The time has come to go on the offensive.\n\nSomething sinister is underway above us, on the Lightning Ledge. It is time to unleash the fury of the ancients!\n\nFly up to the Lightning Ledge and demolish the Twilight's Hammer there. Crush them, {name}, slay their creations and hurl their bodies from the mountainside!", completion = "Impressive, {name}. Very impressive.\n\nYou embody all of the strength of the Wolf Ancient, and possess the wisdom to use your powers well. I salute you.", objectives = "Slay 8 Twilight Stormcallers and 5 Howling Riftdwellers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25355] = { id = 25355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lightning in a Bottle", description = "Lo'Gosh granted me a vision while you were in the hovel, {name}. I saw you striding across the Lightning Ledge, with lightning bolts in your hand. The vision was powerful: Lo'Gosh feels this is of utmost importance. We must not fail the ancient.\n\nUpon the Lightning Ledge, Twilight's Hammer has been experimenting with devices they call \"Lightning Channels.\"\n\nInvestigate one of these channels, then use this totem to summon the Spirit of Lo'Gosh and learn what the ancient is planning...", progress = "We meet again, {class}. You fight well! You carve a path of fear and confusion in your wake.", completion = "So, it is true! You indeed carry lightning in your hands.\n\nYou are the chosen one, {name}. You will be my champion, and carry my vengeance to realms where I cannot tread...", objectives = "Collect a Charged Condenser Jar from a Twilight Lightning Channel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25356] = { id = 25356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Summit", description = "We are staging a relief effort at Westreach Summit for all of Thousand Needles. Shyn will lend you my wind rider to safely get you there. Speak with Kanati Greycloud when you land.\n\nYou must go quickly if lives are to be saved!", completion = "Jawn sent you? Good! We need your help, now!", objectives = "Borrow a wind rider from Shyn and speak with Kanati Greycloud at Westreach Summit in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25357] = { id = 25357, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buy Us Some Time", description = "So many good men have been lost today. Without you, that number would be even higher.\n\nYou have our gratitude.\n\nIf what the shaman says is true, then there is no time to spare. The naga are scouring these waters looking for survivors.\n\nWe are not yet ready to fight. You must buy us time to make preparations. Find the naga that hunt us and delay their efforts.", progress = "Have you given the naga something to think about, {class}?", completion = "Let's hope your efforts prove to be enough of a diversion...", objectives = "Slay 8 Zin'jatar Raiders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25358] = { id = 25358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nerve Tonic", description = "How am I feelin', you ask?\n\nWell, after bein' yanked from the deck of our ship by a giant sea monster and then left to drown in the sea... not so good!\n\nMy nerves are gettin' the best of me, to be honest.\n\nIf you could round up some of the supplies that are sure to be floatin' around the nearby wrecks, I could likely whip up somethin' that'll take the edge off...", progress = "Were ya able to grab some supplies, {race}?", completion = "I trust we both know what's been going on inside these crates...\n\nThat's right... ferrrmenntation! Here y'are. My personal secret recipe.\n\nYou wouldn't get this from any other guy!", objectives = "Mack wants you to collect 5 Sunken Cargo in Kelp'thar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25359] = { id = 25359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Toshe's Vengeance", description = "You met Toshe back in Damplight Cavern, didn't you? He followed some of the fleeing naga to a set of ruins to the east and then sent for help.\n\nFind Toshe at the ruins as soon as you can. If you find out anything about what the naga want, please let us know.", completion = "I remember you. You were there when they attacked us back in the cave.\n\nGood to have you with me, {class}. Ready for a little vengeance?", objectives = "Speak to Toshe Chaosrender at the Ruins of Thelserai Temple.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25360] = { id = 25360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crabby Patrons", description = "These crabs are not friendly. Not. Friendly.\n\nSam's endless drilling is riling them up. I know from experience that there's no stopping Sam, so let's look into the other side of things, shall we?", progress = "Careful. They pinch.", completion = "Does everything down here only come in jumbo size? Oooh! That's a thought. Maybe there are some hunky sea goblins around here somewhere.\n\nThanks, by the way.", objectives = "Kill 10 Green Sand Crabs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25361] = { id = 25361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Cloak's Sheen", description = "Well met, {class}. I've traveled with my companions down to Feralas on a mission for our Orgrimmar masters.\n\nMy life-mate Korrin finds great pleasure in new clothing, so I aim to make her a new cloak adorned with the gossamer wings of faerie dragons. Would you be able to help me? Sprite darters with the gorgeous wings I want are west of Camp Mojache.", progress = "The sprite darters can be dangerous critters when provoked. Be careful when dealing with them, {class}. And be even more careful of any night elves in the area. The pestering fools tend to hold up in the forests also.\n\nWhen you've gotten enough of the wings, let me know, I'll be sure to reward you well!", completion = "Wonderful, {class}! These will do nicely. There are enough here to make a cloak for Korrin, and possibly even more! Thank you.\n\nI hope the trip wasn't too dangerous? The area of Feralas is not known for being forgiving, but you've obviously done well enough.\n\nThank you again, {class}.", objectives = "Bring 10 Iridescent Sprite Darter Wings to Krueg Skullsplitter in Camp Mojache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25362] = { id = 25362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Grim Discovery", description = "The Grimtotem clan! Those gutless traitors are still lurking around here, eh...\n\nYou have to go back, {class}. Go back and bring me their horns... piles of them if you can. The Grimtotem are not to be trifled with or underestimated. Go back and slay them; let the rivers in Feralas run red with their dark blood.", progress = "Take my words seriously, {class}, the Grimtotem clan is evil. If you've found their whereabouts, then it's up to you to return and strike the first blow against their clan... before they can come into our own lands and raze our own villages, or pilfer our lands.", completion = "Traitors to the Horde and traitors to their own people...\n\nI guess they're not all bad. They'll make fine drinking flasks.", objectives = "Bring 20 Grimtotem Horns to Krueg Skullsplitter in Camp Mojache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25363] = { id = 25363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War on the Woodpaw", description = "The gnolls... they are more than a nuisance.  They are a constant threat to the existence of this very camp!  It is irrelevant whether they are indigenous to Feralas or not; if we do not strengthen our resolve against them, we will find ourselves driven out of the entire region.\n\nThe gnoll attacks against the camp have become more fevered as of late.  We need your aid in thinning their numbers; bring to me ten of their manes, and I will reward you handsomely for your effort.\n\nGo!", progress = "We drive them back, and yet they still attack!  Someone or something must be driving them into a frenzy... oh, you have returned, eh {name}?  Do you have the manes I require for the bounty to be met?", completion = "This is proof of a good start, {name}.  Your skills as a soldier are to be commended.\n\nYou are not the only one I ask that task of.  Many before you have fought them, and in times past, our efforts have kept them at bay.  Recently though, their attempts to push northward into our area of influence have increased dramatically.  Their attacks have also become more savage... almost as if they were desperate.\n\nI have a plan though, {name}, that might settle things once and for all against them...", objectives = "Bring 10 Woodpaw Gnoll Manes to Hadoken Swiftstrider in Camp Mojache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25364] = { id = 25364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alpha Strike", description = "Gnolls are unfortunately as resilient as they are brutish and stupid. I have driven back the gnolls time after time from our camp, and it is only our chieftain's mercy that prevents them from being wiped out entirely.\n\nOver the years, it has fallen into a dance of strength and dominance. When their numbers surge and they threaten the camp, the alphas, the strongest gnolls, must be slain.\n\nThis will drive them back into the forest, and leave us is peace until they forget their lessons.", completion = "You've done as I have asked, and for that I salute you.  Take this small reward as compensation for your efforts, {name}.\n\nWith their numbers thinned and their leaders slain, the gnolls will think twice about storming the camp.  This doesn't conclude the issue at hand, however...\n\nThere must be some reason why the gnolls have been whipped into such a frenzied state.  Before they have a chance to regroup, I want to find out what is causing it.", objectives = "Kill 5 Woodpaw Alphas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25365] = { id = 25365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Woodpaw Investigation", description = "Gnolls aren't the sharpest tools in the shed, but they will no doubt have some sort of documented strategy on their recent activity. If we were to find those plans, then we'd have a clearer idea of what is making them so worked up.\n\nI want you to head back to the Woodpaw and find anything that might resemble their battle plans. They have to have something--their attacks have been too coordinated to be done without them. Find them, and return to me when you have them.", completion = "Examining the map reveals it to be the battle plans that Hadoken Swiftstrider wants.  Numerous arrows that perhaps represent troop movements are drawn on the map, though most seem to be headed toward the south rather than to the north where Camp Mojache lies.\n\nAnother section of the map has a picture of what you think is a large insect of some kind, with various tick marks under it.  From the looks of the gnolls, it perhaps represents their losses against the unknown bugs...", objectives = "Find the gnoll battle plans somewhere in the gnoll camps to the south of Camp Mojache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25366] = { id = 25366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle Plans", description = "With the battle plans of the gnolls discovered, all that now remains is to bring the plans back to Hadoken Swiftstrider in Camp Mojache.  Perhaps he or someone there can make further sense of what the gnolls are up to.", progress = "Welcome back {name} - were you able to find some tangible evidence as to the plans of the gnolls?", completion = "Ah, this is exactly what we needed.  While I am not so skilled at ciphering what most of the scrawling on this map is, I've seen enough battle plans in my day to understand what is happening with the gnolls.  It looks like they are currently fighting a two front war.  One is with us... but it seems that their main energy has been against a foe to their south.\n\nThere's more at hand here than meets the eye.  Perhaps it is time to figure out who this other foe they face really is.", objectives = "Bring the Woodpaw Battle Plans to Hadoken Swiftstrider in Camp Mojache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25367] = { id = 25367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zukk'ash Infestation", description = "From what scouting we have managed to muster, we believe that the foe south of the gnolls is an insect-like race.  Frankly, it is irrelevant whether or not they're sentient.  If they are driving the gnolls to frenzy against us, then they are as big of a threat - if not more - than the gnolls.\n\nDive deep into where these Zukk'ash insects dwell; it is known as the Writhing Deep.  Thin their numbers and report back to me what you find, bringing back their carapaces as evidence of your handiwork.", progress = "How goes the hunt, {name}?  Are you here to report your success?", completion = "Well done, {class}.  Though the extensiveness of the Zukk'ash presence will not be thwarted with anything less than a full-scale invasion, you have bought us some time so we can devise a proper strategy.\n\nI will be sure to have these carapaces analyzed; we'll need to learn everything about them before we deal with what has unfortunately turned into a much larger issue than we had anticipated.", objectives = "Bring 20 Zukk'ash Carapaces to Hadoken Swiftstrider at Camp Mojache, Feralas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25368] = { id = 25368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verinias the Twisted", description = "The other spirits and I are bound here by a cruel demon named Verinias. He is our captor, a twisted, mindless beast who devours our souls over millennia.\n\nThe lure of the souls and arcane magic you've brought me should let you draw him out. Take this condensed essence to the dead tree at the far north of the ruins. Use it to lure Verinias and slay him, that I may finally be free...", progress = "You must free me from Verinias's grasp! I can grant the amulet to you if you do...", completion = "I'm free...finally! Oh, it feels so good to be free...\n\nOh, you saw, didn't you?", objectives = "Defeat Verinias the Twisted.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25369] = { id = 25369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stinglasher", description = "In surveying the Writhing Deep, one of our scouts reported seeing a giant insect - much larger than the other insects spotted - wandering about the twisted terrain.  Not only is it larger, it also seems to secrete some sort of aura that the other insects don't.  We've given it a name - Stinglasher.\n\nThe innards of this beast would be invaluable to study as we figure out the best way to deal with this new threat.  Cut out its secretion glands and bring it back to me immediately!", progress = "Have you managed to bring down Stinglasher yet?", completion = "Impressive, {class}... most impressive!  If Stinglasher is indeed one of their strongest creatures, the study of the beast will prove to be quite valuable in time.  It's now my charge to make sure we defend ourselves long enough to take advantage of it.\n\nPlease accept this coin bounty as a token of the entire camp's thanks, {name}.  Well done.", objectives = "Defeat Stinglasher in the Writhing Deep, bringing its glands back to Hadoken Swiftstrider at Camp Mojache, Feralas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25370] = { id = 25370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inciting the Elements", description = "This is no mere natural occurrence, {name}.  There must be a twilight presence behind our lines that we haven't accounted for.\n\nIt's possible that whoever is instigating the elemental disturbance is using foul magic to hide themselves from our sight.\n\nSeek the aid of the faerie dragons that roam near the World Tree; they can see through any of our enemy's illusions.\n\nFeed them the juniper berries that grow nearby to gain their trust.", progress = "Back already, {name}?", completion = "You've done well, {name}.  We cannot allow the Twilight's Hammer spies this close to the world tree!", objectives = "Feed Juniper Berries to the Faerie Dragons and slay 4 Twilight Inciters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25371] = { id = 25371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Abyssal Ride", description = "If you are going to be making it anywhere in this kelp forest, we need to get you a reliable mount. I think I've come up with a better plan than the sea turtle, and it's not far.\n\nTie off a lure at the rope just west of us, and then mount the seahorse that it will attract.\n\nBe warned, you may need to work hard to break the beast.", progress = "The grace of these creatures is astounding. They will make the perfect mounts.", completion = "Amazing! You look exhausted. She must have really made you work for it.\n\nLife should be a lot easier down here going forward with a mount that swift at your beckoning. Congratulations, {name}!", objectives = "Lure and subdue an Abyssal Seahorse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25372] = { id = 25372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aessina's Miracle", description = "<The finger-like branches of one of Nordu's burning limbs part, revealing an untouched, glimmering seed.>\n\nThis is the Heart of the Forest. The seed of life.\n\nTake this to your Arch Druid at Aessina's Grove - Hamuul Runetotem will know how to invoke its power. I promise you, the wilderness spirit will be silent no longer. New life will bloom from the ashes of old.\n\nThank you, {race}. My time is done.", progress = "I am at my wit's end, {name}! Aessina is silent.\n\nHave you found something? What is this?", completion = "This is the key, {name}! With the seedlings you collected for me earlier, the animals you've saved from around Hyjal, and the Heart of the Forest you've just discovered, we can rejuvenate this land right from under the feet of Twilight's Hammer. Imagine their astonishment to see their work undone, as life triumphs over chaos...\n\nI will begin the ceremony at once!", objectives = "Take the Heart of the Forest to Hamuul Runetotem at the Grove of Aessina in Mount Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25373] = { id = 25373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hilltop Threat", description = "I am proud of Mojache's reputation as a safe haven in the wilds of Feralas, but the camp faces many threats. The Gordunni ogres gather nearby in the northern foothills, claiming their territory and despoiling the wildlife.\n\nWith the arrival of our brothers and sisters seeking shelter, I cannot let them linger any more. Go north and drive the ogres out.", completion = "I thank you, {name}, but there is more work to be done to keep the camp safe. Listen further.", objectives = "Kill 5 Gordunni Hillguards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25374] = { id = 25374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sasquatch Sighting", description = "You may have seen this with your own eyes, but my longrunners have reported something disturbing to me. The gordunni in the hills have captured an enormous sasquatch from the wilds.\n\nI don't know how long it's been held, but ogres are not ones for hobbies. I fear they plan to unleash the tortured beast on Camp Mojache.\n\nReturn to the deepest corner of the Gordunni Outpost and slay the sasquatch, {name}.", completion = "I will be able to rest easy now, {name}. You've saved our camp from a terrible menace.", objectives = "Kill Bigfist.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25375] = { id = 25375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming The Tamers", description = "The gordunni are not known to tame animals. If they're learning, this is cause for alarm. While the sasquatch they've tamed may be the major threat to our camp, the gordunni who captured him should be dealt with as well. If left, they may simply capture another.\n\nKill the gordunni tamers, and make sure the ogres know their efforts will not be tolerated!", completion = "Good, good. Let's hope the ogres are at least smart enough to realize we're sending a message!", objectives = "Kill 6 Gordunni Tamers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25376] = { id = 25376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gordunni Cobalt", description = "I just arrived here in Feralas, and I've heard that the Gordunni Ogres that inhabit the wilds here have some interesting minerals. Who knows what they are up to, but they sure are protective of that stuff! They don't leave it just lying around; no, they bury it to protect folks like me from getting their hands on it.\n\nIf you'd be willing, I'll give you my shovel. Go to the Gordunni Outpost north of here and dig me up some Gordunni cobalt. Look for the blue glow, then start digging!", objectives = "Obtain 12 samples of Gordunni Cobalt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25377] = { id = 25377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde's Hoard", description = "It is unclear what manner of creature scrawled the seemingly random markings on this piece of parchment, but upon close inspection, some of the obscure shapes begin to look like landmarks.\n\nScanning the sea floor, you think you recognize a few points of reference, one being a nearby sunken ship. If your guess is correct, there appears to be treasure of some kind near the wreck.\n\nYou cannot help but wonder what the scaly, serpentine figure on the map might represent....", progress = "This slightly encrusted lock might still be functional.", completion = "You've discovered lost treasure!\n\nYour mind reels at the thought of what else might be hidden in the depths of the sea.", objectives = "You must defeat Akasha to obtain the Horde Chest Key which you must then use to open the Sunken Horde Chest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25378] = { id = 25378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ysondre's Call", description = "The dragons of nature... Heed her call, {name}. Do not linger here. Her request for your aid is both a great honor and an omen of terrible danger.\n\nThe place she spoke of is called the Emerald Summit. A path off the main road through the Lower Wilds leads up one of the high stone plateaus; you will find a small shrine at the top.\n\nAll of Feralas may rest upon your shoulders. May the Earth Mother watch over you.", completion = "You've come.\n\nI am ashamed to ask this of you, {class}, but I've ran from him long enough. Taerar must be stopped.", objectives = "Speak with Ysondre at the Emerald Summit in the Lower Wilds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25379] = { id = 25379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taerar's Fall", description = "Emeriss and Lethon are gone. It's only us left now. I can hide from this no longer. All I did while a part of that brood...all the suffering I've caused...must be repaid today.\n\nI am still weak, {name}. I cannot assume my true form even if I dare try. But I will still stand beside you in battle.\n\nIf you are prepared, I will call Taerar to us. He will be unable to resist the temptation of revisiting corruption upon me.", completion = "It is done.\n\nThis land that has suffered so much can rest now.", objectives = "Defeat Taerar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25380] = { id = 25380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spreading The Word", description = "Welcome to the farm, {name}. Everyone here works to earn <his/her> keep. For some, that means caring for the animals. Others are responsible for working on our construction projects. Still others work to spread our message among the people and I think that's a good place for you to start.\n\nTake this board. It bears a short message about our beliefs. While wearing the board, visit the eastern and western zeppelin towers outside Orgrimmar's gates, as well as the town square of Razor Hill, to the south.", completion = "Well done, {name}. It might be awkward at first, but you will get used to advocating our beliefs in public. It is one way of remembering our obligation to bring the truth to others. We must save as many as we can.", objectives = "While wearing your Doomsday Message, visit the East Zeppelin Tower, the West Zeppelin Tower, and the town square of Razor Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25381] = { id = 25381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fighting Fire With ... Anything", description = "The inferno raging up ahead marks the front line between us and the forces of the Fire Lord. The fire elementals unleashed here are unlike any I've ever encountered.\n\nCan you help us stem the tide of destruction? Slay the raging firestorms... before they engulf Aessina's Grove and erase all hope of someday reclaiming this mountain!", completion = "Thank you, {name}. You've given us the opportunity to try to reclaim the upper hand.", objectives = "Slay 10 Raging Firestorms within the Inferno.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25382] = { id = 25382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disrupting the Rituals", description = "The firestorms up ahead are unbound elementals in the purest form - something I didn't think could exist outside their own plane. Only very skilled summoners could unleash something like this.\n\n{name}, head into the Inferno and seek out Twilight Inferno Lords. They've got to be summoning in reinforcements as we speak. Silence them... For good!", completion = "Dead? Good!\n\nBut it seems there's still so much to be done... fires to quench... and the soil to heal...\n\nI hope you'll stay close and help us reclaim Hyjal!", objectives = "Slay 6 Twilight Inferno Lords within the Inferno.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25383] = { id = 25383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ysondre's Farewell", description = "With that, I am the only one left.\n\nEven if I choose to remain in this world, I cannot rejoin the green flight. But this victory gives me hope. Perhaps, in time, I can find peace in a simple life among mortals.\n\nYou must return to your people. Tell them that the dragons of nightmare are gone, and will no longer threaten these lands.", completion = "You are truly blessed by the Earth Mother, {name}, to have the honor of fighting with the guardians of nature, and to also survive it.\n\nKnow that you have kept safe every living soul in this camp, and possibly this entire forest. Take these gifts with my deepest thanks.", objectives = "Speak to Chief Spirithorn in Camp Mojache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25384] = { id = 25384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raw Materials", description = "Thank you, {class}. We owe you our lives.\n\nBut if we're ever to see the surface again, we'll have to fight our way out of here. That means I'm going to need to craft some weapons and armor.\n\nBefore you found me, I saw a soldier eaten by one of those orca up there.\n\nI'll wager that if you cut a few of them open, you'll find plenty of scrap metal for me to work with.\n\nIf you don't want to swim up to them, I bet you could lure one down to you with some entrails...", objectives = "Samir wants you to collect 3 Rent Scrap Metal from Frenzied Orca in the Kelp Forest.\n\nYou can lure an orca using Pincer Entrails from Clacksnap Pincers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25385] = { id = 25385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Save the Wee Animals", description = "Help us, {class}! The forest is aflame, and the wee animals can't find their way out. They can't fight for themselves, with their teeny-tiny little teeth and their soft furry paws! They're fluffy and sweet.\n\nThey have wet little noses!\n\nIf you don't save them, I don't want to even THINK about it.\n\n<She slaps her palms over her eyes.>\n\nI'm not thinking!", progress = "Did you save the wee animals? And their wee little friends?", completion = "Squueeeee!\n\nDid the nice Mr. {class} pull you from the flames, little friend? You're safe now!\n\nHooray!", objectives = "Go into the Inferno and rescue any combination of 10 Panicked Bunnies or Terrified Squirrels.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25386] = { id = 25386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Stonemaul Hold", description = "You must send word of what has happened here, {name}. To the south is Stonemaul Hold. There, our allies have gathered the few ogres of the horde to fight against those despoiling these forests.\n\nSpeak with Orhan Ogreblade. She leads the Stonemaul clan here, and will need to know of all that has occured. And be wary, lest some of this corruption remain...", completion = "You've been tussling with drakes, eh?\n\nI like it. We need someone who can pull their own weight around here. Are you ready to fight for the Horde?", objectives = "Speak with Orhan Ogreblade in Stonemaul Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25387] = { id = 25387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Camp Mojache", description = "You've done a hell of a job here, {name}. With the Twilight's Hammer shamed and the Gordunni left bleeding and broken, we'll be able to set our sights on the true battle with the Alliance here.\n\nIt'll take time to build our forces enough to match the night elves infesting this place. I'm sending you ahead to Camp Mojache to the east; they've got problems of their own, and we can't let any Horde territory fall here.\n\nLok'tar!", completion = "I am thankful you've come, {class}. Our camp is beset by many perils, and yet we must tend to those fleeing the devastation of the cataclysm.\n\nIf there is to be any refuge here, you must help us.", objectives = "Speak with Chief Spirithorn in Camp Mojache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25388] = { id = 25388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crate of Crab Meat", description = "This crate, labeled 'Crab Meat', seems to have fallen from a recently sunken cargo ship.\n\nAdarrah would surely welcome such a find, considering the ordeal she's had to endure.", progress = "What have you got there, {name}?", completion = "Why, {name}! What a surprise!\n\nIf anyone ever calls your character into question you be sure to send them my way.\n\nI'll tell anyone who'll listen that in my moment of need, you gave me a case of crabs...", objectives = "Take the Crate of Crab Meat to Adarrah in Smuggler's Scar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25389] = { id = 25389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Taste For Tail", description = "It could be days before we're ready to make our way to the surface, and to be honest, I'm already beginning to get hungry.\n\nI hate to be picky, but when it comes to seafood, I'm afraid there are very few things I can stomach.\n\nIf you come across any lobster types, I would happily pay you what coin I have with me for their tails.", progress = "Oh, please tell me you were able to find me some food, {class}.", completion = "Oh, my!\n\nThat's some of the biggest, juiciest tail I've ever seen!", objectives = "Adarrah wants you to bring her 4 Clacksnap Tails.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25390] = { id = 25390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Girl's Best Friend", description = "Let's just get it out in the open. I'm no stranger to love, {name}.\n\nOver the years, if there's one thing I've learned, it's that love's tangible treasures last longer than the flames of passion.\n\nI've managed to collect my fair share of these gifts - gemstones, rings, necklaces, and the like, and I carry them with me wherever I go.\n\nAt least I used to...\n\nWhen I was swept from the ship, my valuables were scattered across the sea. Help me recover them and I promise to make it worth your trouble.", progress = "Well, {race}?\n\nWere you able to recover my valuables?", completion = "Oh, you've found them! I was sure they were lost forever...\n\nHere you are, {name}. I hope this is ample payment.", objectives = "Adarrah wants you to recover 6 Adarrah's Keepsakes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25391] = { id = 25391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weapons of Spirit", description = "Imbuing the muisek into the weapons is a difficult process. Now that I have all of the required materials and the muisek of the creatures that you captured, I may begin. Please wait; I will return in a moment.", completion = "As promised, you have your choice, {name}. The muisek of the creatures has been forever sealed into the power of these weapons.\n\nYou may now wield their energy as your own. Use it well.", objectives = "Witch Doctor Uzer'i wants you to wait for a moment while he prepares the weapons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25392] = { id = 25392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh, Deer!", description = "Do you speak deer? It's all in the nose.\n\n<She points to her nose.>\n\nThe does have fled the fires, but their little fawns - Some of them are still trapped in the burning and the hurt!\n\nGo back into the Inferno and escort three injured fawns back here to their mothers right here beside me.\n\nPlease save the little fawns, or I'll give you the big eyes!\n\n<Her eyes grow big and dewy.>", progress = "Hurry! I can smell the smoke!", completion = "Oh yay! Happy little deer!\n\nNow they can grow up and have ADVENTURES.\n\nYou're swell.", objectives = "Rescue three Injured Fawns from The Inferno and escort them back to Mylune at the Grove of Aessina.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25393] = { id = 25393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Gnomeregan", description = "Momentarily, the multi-phased assault upon Gnomeregan will begin and Mekgineer Thermaplugg and his men will be brought to justice!  Too long has Thermaplugg festered in the depths of our home, defended by a corrupt and irradiated army.\n\nThe assault begins in but a moment! Be ready recruit, this fight will not be for the faint-hearted.", objectives = "Help King Mekkatorque with the assault on Gnomeregan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25394] = { id = 25394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Than Illness", description = "I've discovered a brood of dragon whelps gathered off the road to the north with a similar affliction. Green dragons are sacred custodians of nature. The fact that this disease is capable of spreading to them is cause for great alarm.\n\nWe must stop this from spreading further through any means. Slay the infected whelps, {name}, and return to me.", completion = "This development worries me greatly. This has happened before...", objectives = "Kill 10 Noxious Whelps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25395] = { id = 25395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stolen Keg", description = "You've got to help us, <lad/lass>. We were tasked with escorting a precious cargo to our fellow dwarves...a keg full of the finest ale you can get out here!\n\nUnfortunately, bird-brain over here fell asleep on the job! Those blasted orcs took our keg, and hauled it up into Dun Algaz where they're hiding.\n\nThis can't stand! Now, while I stay here and try to convince this idiot that it was his fault, I'd like you to go in there and get our keg back. For Khaz Modan!", progress = "Do you have it? Is the poor thing intact?", completion = "Thank the Makers! It's downright pristine. Those orcs couldn't figure out the tap-lock, it seems...and couldn't hack through the mastercraft work of Ironforge's keg-crafters with their crude weapons!", objectives = "Retrieve the Mountaineer's Ale from Dun Algaz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25396] = { id = 25396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tears of Stone", description = "As you witnessed, the dragon Ysondre has told us that the tears of the land can seal the portal from which this corruption stems.\n\nHer words ring true; in the glade to the west, I have seen the mountain giants distraught. They raged in frustration and wept, and their tears fell upon the stones as shining crystals.\n\nThough the giants weep no more, these stonetears must be what Ysondre referred to. We must gather them.", progress = "The tears are among the very rocks that the giants themselves rise from. There should be loose ones near the base of these large monoliths.", completion = "The mountain giants are precious allies of our race. We must stop this corruption before it claims any more creatures of the forest.", objectives = "Collect 7 Stonetears.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25397] = { id = 25397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Land, Corrupted", description = "The cliff giants of Feralas are extensions of the earth itself, {name}. When nature thrives, they are benevolent protectors and peaceful guardians.\n\nBut as the forest is tainted, so too are they.\n\nShould they be corrupted by this malady, they will lash out in violence against trees, wildlife, and the very boulders they were shaped from.\n\nBe wary in your tasks. Should you find any corrupted giants, destroy them, for the sake of those still spared.", completion = "The spirits of these guardians will return in time, {name}. You've freed them to move on in nature's cycle.\n\nNow it falls to us to make sure that cycle is free of corruption and needless suffering.", objectives = "Kill 6 Corrupted Cliff Giants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25398] = { id = 25398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sealing the Dream", description = "It is ready. Take this, {name}; a beacon of natural essence, blessed by the will of Ysondre.\n\nTo the north, on the other side of the flowing brook, is Dream Bough. There stands the Great Tree, the tallest in Feralas, a sapling of the very World Tree. A portal to the heart of the Emerald Dream sits in its trunk, and it is this portal you must seal.\n\nThe portal will be guarded, but you must be brave.", completion = "Your bravery has seen us through! The Emerald Nightmare has been shut out from this land.\n\nThe fate of the dragon Taerar worries me...but there is much work still to be done. I cannot afford to dwell on it.", objectives = "Use Ysondre's Tear to seal the portal at Dream Bough.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25399] = { id = 25399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hatecrest Forces", description = "The Hatecrest are fighting fiercely! Their leader is a priority, but we need to kill as many of them as we can.\n\nGo ahead of me, I'll meet you on the battlefield. Show them no mercy!", completion = "Your valor was mentioned in my briefings, {name}. I commend you.", objectives = "Kill 10 Hatecrest Naga.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25400] = { id = 25400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gordunni Threat", description = "Estulan, the Highborne up in the tower, is reclusive. I haven't been able to speak to him very much. He has, however, told me that the ruins of the High Wilderness to the south are full of Gordunni ogres.\n\nThe ogres are not only a threat, they're destroying any forest and wildlife nearby. Estulan has also warned me of what might happen if they discover any artifacts of Highborne power among the ruins...\n\nHead south, {name}, and slay any Gordunni you find!", completion = "It sounds like there were more than we thought! Thank you for your brave work, {name}.", objectives = "Kill 16 Gordunni ogres in the High Wilderness.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25401] = { id = 25401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gordunni Orb", description = "In addition to clearing out the ogres...\n\nEstulan mentioned something else about the ogres. He said the ogre warlocks may have some sort of orb, or other item of power\n\nHe was terse about it, but seemed upset...he said there was \"no way they could be Highborne\", so I think he wants to know just where they got them. Bring me back one of these orbs.", progress = "Do you have the orb?", completion = "Is that it? Let me see here...", objectives = "Collect a Gordunni Orb from a Gordunni Warlock.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25402] = { id = 25402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Estulan's Examination", description = "He's right. I haven't been among the night elves long, but I can tell these markings are completely unlike any kaldorei decorations...\n\nEstulan needs to see this. Take this up the tower to him. He may be surly, but don't be dissuaded; once he sees the orb, he'll realize it's an important issue.", progress = "What is that you're holding?", completion = "Ahh, the orb I mentioned before. A decent reason to disturb me.", objectives = "Deliver the Gordunni Orb to Estulan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25403] = { id = 25403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogre Abduction", description = "This is neither a crude ogre trinket, nor an ancient relic made by my kind. Its specific construction is new to me...and this fact disturbs me greatly.\n\nThe wolf-girl will be sending you to Dire Maul soon, to fight the Gordok elite. They are the leaders of the Gordunni, and would know who is supplying these.\n\nTake the orb back, I've cast a few enchantments on it. Hold it up in front of a weakened Gordok ogre, and once you've captured him, bring it back here.", completion = "Ah, you've brought him. Now I merely have to suffer the fate of speaking to him.", objectives = "Use the Modified Soulstone to capture a Gordok ogre.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25404] = { id = 25404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If You're Not Against Us...", description = "South of here you'll find a solitary tower, known as \"Blackhorn's Penance.\" Upon it is bound a demon: Tyrus Blackhorn.\n\nYou may think me mad for turning to an old foe for help, but Blackhorn was once a mortal, and I can't imagine he wants to watch Twilight's Hammer triumph.\n\nSpeak with Blackhorn, and see if you can convince him to help us in our fight. He may yet redeem himself.\n\n...Just don't set him free!", progress = "You were sent here to talk, {race}. So. Talk.", completion = "Very well, {race}. I will help you mortals, even from within my bonds.\n\nBut don't sicken me by claiming it's my redemption. I do this for my own ends.", objectives = "Speak with Tyrus Blackhorn and convince him to help in the fight against the Twilight's Hammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25405] = { id = 25405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rest For the Weary", description = "You have done well, {race}, but there is much more to do and I grow weary.\n\nI have expended a great deal of energy sending a distress message to Earthen Ring leadership, pleading for their help.\n\nI must rest if I am to be of further use to us here.\n\nSpeak to the leader of the men you've saved and do what you can to help them prepare for battle.\n\nThe naga are scouring the waters for us. It is but a matter of time before they return - and they will surely come in even greater force.", completion = "I hear you, {race}.\n\nI understand the urgency, but these men are in no condition to fight.", objectives = "Speak with Captain Taylor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25406] = { id = 25406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gordok Guards", description = "With the nearby ogres dealt with, we should take the offensive and press our attack into their territory.\n\nThe Gordok ogres are the head of the Gordunni clan, ruling them from the ruins now called Dire Maul. They are stronger than the lesser Gordunni, but I have no doubt you can handle them, {name}. They won't know what hit them.", completion = "Wonderful! Everything's going according to plan. Lady Shandris will be pleased.", objectives = "Kill 6 Gordok Enforcers and 6 Gordok Ogre-Mages.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25407] = { id = 25407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forces of Nature: Wisps", description = "The Sentinels make up the bulk of our forces here, but a well-rounded night elf army requires more than just night elves. The creatures of this forest, our ancestral home, have protected us for centuries. We simply need to rally them.\n\nTake this whistle. Our allies know this sound, and you'll be using it to recall them.\n\nBefore you start gathering creatures, I'd like you to recall a few of our wisps, just for practice. You can find them just outside the fortress, among the trees.", completion = "Wisps have always lived in harmony with night elves, and we depend on them for many things. These little guys you sent back, for example, will be helping us with some new construction and repairs.\n\nReady for more?", objectives = "Use Tessina's Whistle to recall 3 Feathermoon Wisps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25408] = { id = 25408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeds of Their Demise", description = "We will decimate the Twilight's Hammer by corrupting and subverting them. \n\nSeeing that you have no intention of releasing me from my bonds, I require you to collect some reagents for me. My own demonic essence has corrupted the plant life around my shrine here. I need you to harvest some bileberries from the wailing weeds that surround this tower.\n\nMy little pets will attempt to harvest YOU in return. Try not to let them agitate one another.", progress = "Has the local flora been giving you a hard time?\n\n<Blackhorn grins disturbingly.>", completion = "Very good. Please crush the berries into a pulpy liquid. That's quite an aroma isn't it?\n\nNow now, don't gag. It's beneath you.", objectives = "Collect 8 Bileberries.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25409] = { id = 25409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forces of Nature: Hippogryphs", description = "Hippogryphs are majestic creatures. Some say they were created by Cenarius himself as a gift for the night elves. They're wary of other races, but they're intelligent enough to recognize a friend of a friend.\n\nI need more hippogryphs here so we can begin training some of our newer archers to ride them. Take the whistle again and rally the Frayfeather hippogyphs in the grove just south of the Tower of Estulan.", completion = "A properly trained squadron of hippogryph riders can take on nearly any opposing force. Feathermoon Stronghold will be much safer with these noble beasts on our side.", objectives = "Use Tessina's Whistle to rally 10 Frayfeather Hippogryphs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25410] = { id = 25410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forces of Nature: Treants", description = "Some people think treants are good for little more than fetching drinks in a war. Most of them haven't seen an entire defensive line scattered by what they thought was cover.\n\nAnd have you ever seen a peon try to chop one down and get surprised? I was in tears...\n\nAt any rate, they're immensely valuable allies. You'll find some wandering just outside  the Tower of Estulan and more in forest to the east, just southeast of Dire Maul. Be on the lookout for the Horde!", completion = "They may not look it, but some treants grow to be ancient protectors. We could use a few more of those around here...", objectives = "Use Tessina's Whistle to rally 6 Wandering Forest Walkers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25411] = { id = 25411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Master", description = "The potion you created is vile enough to wake the dead. Which is its intended purpose.\n\nSlay a Twilight Inferno Lord and force the brew down his throat. He will revive, if only briefly, and be completely under your dominance.\n\nSpeak with him and learn the true name of the fire elemental he is channeling into the world to burn down your precious forest.", completion = "<The wretched creature before you speaks in a wavering voice, its body broken but briefly animated by Blackhorn's vile potion.>\n\nYes, master?", objectives = "Use the Bottled Bileberry Brew on the corpse of a Twilight Inferno Lord, then speak with him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25412] = { id = 25412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Name Never Spoken", description = "We called upon the fury and flame of the One, my former master.\n\nThe Inferno is by His design.\n\nHis true name is never uttered, it holds His power.\n\nEach of us was told but a piece. Each piece engraved on a firestone.\n\nThe One's true name is here, in the Inferno. Seek the three stones...", completion = "Yes, yes! Show me the runes you discovered.\n\n\"Vol'talo Thol'embaar.\" That's the name of your real enemy.\n\nPresumably you're dealing with one of Ragnaros's generals, sent here to scorch the mountainside and pave the way for his conquest.\n\nI will show you how to crush him.", objectives = "Assemble the true name by examining the three Firestones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25413] = { id = 25413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Change of Plans", description = "Alright, kid. Slight change of plans...\n\nI think I've figured out a way to finish off that monster and you're going to assist me.\n\nThe way I see it, you owe me until my work is done here, and I ain't leaving without that artifact.\n\nFirst I need you to search those old wrecks for some good rope and a serviceable harpoon.\n\nThen... well, I'll fill you in on the rest later.", objectives = "Get the Rusty Harpoon and 3 Coils of Rope.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25414] = { id = 25414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing", description = "The cult isn't just spreading fear and paranoia anymore. Now, I'm receiving reports of missing people. Mothers, fathers, brothers, and sisters have seemingly disappeared, but I have a feeling they can be found in one of the cult's camps outside the city. If I give you the names of some of the missing people, would you try to locate them in the cultist camp at Mirror Lake Orchard? It's southwest of the city gates. To blend in, you'll need join the cult and get a robe from one of the doomsayers in Old Town.", completion = "So you found them? Why did the missing men and women not return with you?\n\n<You tell the captain that they seemed determined to stay for various reasons.>\n\nThen we cannot force them to come home. I can only hope that in time, the cultists will realize the harm their actions have caused and decide to return to their normal lives.\n\nThank you for your efforts, {name}. I will tell the families what you found.", objectives = "While wearing your Doomdsay Recruit's Robe, speak to Cultist Lethelyn, Cultist Kaima, Cultist Wyman, and Cultist Orlunn at Mirror Lake Orchard in Elywnn Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25415] = { id = 25415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spreading The Word", description = "Welcome to our orchard, {name}. Everyone here works to earn <his/her> keep. For some, that means tending the fruit trees. Others are responsible for working on our construction projects. Still others work to spread our message among the people and I think that's a good place for you to start.\n\nTake this board. It bears a short message about our beliefs. While wearing it, visit the Westbrook Garrison, southwest of here, the town square of Goldshire just to the east, and the Valley of Heroes in Stormwind.", completion = "Well done, {name}. It might be awkward at first, but you will grow accustomed to advocating our beliefs in public. It is one way of remembering our obligation to bring the truth to others. We must offer hope to everyone, for we all face the end of this world together.", objectives = "While wearing your Doomsday Message, visit the Westbrook Garrison, the Valley of Heroes in Stormwind, and the town square of Goldshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25416] = { id = 25416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Master's Plan", description = "You're fitting in well here, {name}, but there is more to us than daily chores and spreading the message. I'm sure you heard a little bit about it when you first joined.\n\nAs you know, this world is ending and the unprepared will die painful deaths.\n\nWe have been given a gift, an opportunity to become something greater and more powerful. Overseer Talathor is preparing for a ritual at the altar just west of the orchard. Wait there for him, and learn more of your new brothers and sisters.", completion = "Now that you understand the master's plan, you must prepare to play your part in making it a reality.", objectives = "Learn more about the cult's plans at the altar in the westerm part of Mirror Lake Orchard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25417] = { id = 25417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Doomsday Plan", description = "The first batch of elemental devices are ready. Your task will be to conceal them inside populated areas of Stormwind. The devices will unleash their elementals at the proper time. Don't worry, {name}, you'll be safely away before that happens.\n\nDo not do anything that would draw attention to yourself.\n\n<The overseer hands you a package containing several of the elemental devices. This is just the kind of proof that Captain Anton was hoping you'd uncover. You should probably bring the devices to him.>", progress = "You've returned at last. I was beginning to think that you'd taken up with the cultists for good.", completion = "<You hand Captain Anton the devices that the overseer gave you, explaining the cult's plans.>\n\nCho'Gall is in charge of the cult? Then, it has to be Twilight's Hammer! We suspected that they would try to strike again, but no one knew what form the attack would take.\n\nYou've done an excellent job uncovering this plot. Unfortunately, you won't be the only one they've sent into the city to deploy these devices.", objectives = "Take the Elemental Devices to Captain Anton in Stormwind Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25418] = { id = 25418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thwarting Twilight's Hammer", description = "You can't have been the only person sent into Stormwind to deploy those devices containing wind elementals. We have to find and disable the rest of the devices before they set their captive elementals free to create storms in the city.\n\nAre you familiar enough with the devices to destroy them? Our best chance is to break the devices before the elementals inside can reach full strength. Look for the devices in the Trade District, Cathedral Square and the Mage Quarter. Hurry!", completion = "Excellent work, {name}. Twilight's Hammer will think twice before trying to turn our own people against us again.\n\nWhat worries me is how many citizens joined their movement without thinking about the cult's empty promises. Are times so dire that people will abandon the Light for promises of power and immortality?", objectives = "Destroy Elemental Devices to release their captive elementals. Defeat 5 Raging Wind Elementals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25419] = { id = 25419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lady La-La's Medallion", description = "Dozens of crude gold links make up this heavy chain.\n\nDangling from the center link is an opalescent fragment of what must have once been a large shell-shaped medallion.\n\nYou wonder if the other fragments might be nearby, and if the medallion might be reassembled into its original state.", objectives = "Collect the 5 Medallion Fragments from Gilblin Collectors and combine them to create Lady La-La's Medallion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25420] = { id = 25420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Obstacles", description = "I've studied the gate here for years, trying to find a way of entry that wouldn't disturb any of the ancient architecture just behind it. It figures a few overgrown earthquakes decided to muck the whole thing up! But what's done is done, and the entrance to Uldum is revealed.\n\nI wasn't expecting anything to come out of the ruins before we went in, though. A whole mess of golems are running amok in the valley now, let loose from inside. Someone needs to clean them up if we're gonna get in there!", progress = "Make sure you decomission enough of those stony buggers.", completion = "Good work, {class}. We're that much closer to the secrets of Uldum.", objectives = "Destroy 6 Sandstone Golems.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25421] = { id = 25421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grand Tablet", description = "At the bottom of the chest, you find a large tablet. Made of a material resembling stone, but completely smooth and flawless, it is covered in strange writing.\n\nWhile some resembles the writing on the walls, other scripts appear completely different. Gunstan would probably like to see this.", progress = "You're back! What have you found?", completion = "This is amazing. These hieroglyphs are undoubtedly titan, but the markings below it...\n\nIf I had to hope, this is the same passage written over and over again in an entire assortment of ancient languages. We might be able to use this to decipher the hieroglyphs! If the antechamber was covered in them as you say, who knows what else we'll learn.\n\nI'd like to grant you a fine reward, {name}. We've made the find of the century!", objectives = "Take the Grand Tablet to Gunstan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25422] = { id = 25422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Darkmist Legacy", description = "I am chained to this place...it takes so much effort just to speak to you. I can barely maintain this shape.\n\nI could help you, but please, help me pull myself together first. Once I'm more focused on this plane, I should be able to do it...\n\nIf I could just leave this tomb, the soil itself outside is full of ancient arcane deposits, laying forgotten for centuries. Could you bring me some?", progress = "Do you have the soil? I'm having trouble staying together...hurry...", completion = "Thank you! Thank you...\n\nI feel much better. With just a bit more...", objectives = "Collect 6 piles of Glowing Soil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25423] = { id = 25423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Suffering", description = "You must be careful when you venture forth. Other spirits are bound to this place, malevolent and hateful ones. They've all suffered so much.\n\nNone of what they used to be remains, only suffering and a will to live. We will need that will to summon the overlord that keeps me bound here. Please, gather the essence of the spirits, and bring it back to me.", progress = "Have you gathered it?", completion = "You can feel their anguish, can't you?\n\nMy poor friends. At least we can use you to fix things...", objectives = "Collect 6 Soul Essences.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25424] = { id = 25424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Alysra", description = "I thank you for freeing me, {name}.  I will tell our allies of my findings.\n\nI suggest that you return to the emerald dragon that sent you.\n\nThe Twilight's Hammer does not just seek to gain territory with this particular attack.  They're also after a prisoner.\n\nFandral Staghelm is being held in the Barrow Dens.  The attack doubles as a distraction to free him.  To what end, I cannot tell.  Perhaps our dragon ally can shed some light on this.", completion = "This development is troubling, {name}.  We must act swiftly.", objectives = "Return to Alysra at the Ruins of Lar'donir in Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25425] = { id = 25425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warn King Wrynn", description = "You have successfully defended Stormwind from the threat posed by this Twilight's Hammer cult, {name}, and without harming our own citizens. Our enemy will not rest for long. Indeed, Cho'Gall must already be busy planning his next move.\n\nYou must take word to King Varian Wrynn. Go directly to him in the throne room of Stormwind Keep. Tell the king that our enemies have shown themselves and we must be prepared for their return.", completion = "<The king's face takes on a look of concern, and then anger as you describe the Twilight's Hammer plot to destroy Stormwind.>\n\nHow dare they strike Stormwind? How dare they try to manipulate the people of this city against us and the Alliance! If not for your valor this day, {name}, our city would not have discovered this Twilight's Hammer scheme. You are a true hero of Stormwind and the Alliance.", objectives = "Speak with King Varian Wrynn in Stormwind Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25426] = { id = 25426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War on the Woodpaw", description = "The first of Shandris's direct orders is to deal with the Woodpaw gnolls here. They've been spreading too far, too fast, and are becoming a threat to both the forest and our war effort.\n\nThey know we're here. After we took this camp, we've been leading covert strikes against them. It's time to make a major blow; bring back ten of their manes, and we'll be ready for the next phase.", progress = "The manes aren't just for trophies. If there's to be slaughter, we may as well not let it be a total waste.", completion = "Excellent work, {name}. I didn't think those gnolls would give you much trouble.", objectives = "Collect 10 Woodpaw Gnoll Manes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25427] = { id = 25427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alpha Strike", description = "Never underestimate a threat. These gnolls may seem like simple brutes, but there's animal cunning even among them.\n\nThe gnolls run as a pack, and every pack has Alphas: The biggest, strongest, and most ruthless members that claw their way to dominance. They're the ones giving orders, so they're the ones we're going to slay now.\n\nThey reside mostly around the Woodpaw Den, pushing the others around. Get out there and push harder.", completion = "Perfect. Any gnolls left will be simple prey, lost in the woods.\n\nHeh...here, soldier, take your reward before I get distracted. We've got other threats to deal with.", objectives = "Kill 5 Woodpaw Alphas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25428] = { id = 25428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Black Heart of Flame", description = "Now you will use our newfound knowledge to pull Thol'embaar into the mortal plane like a babe screaming from the womb. Then you will crush him.\n\nThe ritual is simple: take this charred branch, tap it on the ground three times, and utter his name aloud.\n\nYou must call him from within the heart of the Inferno. Destroy him, and bring his black heart back to me.", progress = "Tell me! Have you fought Thol'embaar yet?\n\nI am living vicariously through you, {race}. Do not disappoint!", completion = "There it is! Such a trophy! Born in the fires of another plane...\n\nGo ahead, {race}. Crush it. Crush his charcoal heart in your hands and let the winds scatter the ashes... yes, yes.", objectives = "Use the Charred Branch within The Inferno to Summon Thol'embaar. Kill him and take the Black Heart of Thol'embaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25429] = { id = 25429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zukk'ash Infestation", description = "With the gnolls out of the way, we're ready to take care of other foes. Our scouts have discovered what appears to be a hive nearby, extending deep beneath the ground.\n\nThe insects of the hive are large and ferocious, and most likely pose an even greater threat than the gnolls. I want you to proceed to the hive with caution. Cut down a good portion of the bugs and bring back their carapaces for further study.", progress = "How goes the hunt, {name}?  Are you here to report your success?", completion = "These are silithid after all...I wasn't sure, having never seen one in person. Gilneas had its problems, but at least we didn't have these monstrosities running around!", objectives = "Collect 20 Zukk'ash Carapaces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25430] = { id = 25430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emerald Allies", description = "The druids of Hyjal are not the only ones sworn to defend this land.  The emerald dragons have once again become a powerful ally to our cause.\n\nSpeak to Alysra at the Ruins of Lar'donir, to the north, and see what you can do to help.", completion = "My duties are here, viewing the enemy's movement from above, commanding our armies where they're needed.\n\nYour aid would be most welcome.", objectives = "Speak to Alysra at the Ruins of Lar'donir in Mount Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25431] = { id = 25431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stinglasher", description = "Most of the insects we've seen wandering the hive have been enormous enough, but my scouts reported an especially huge one. It's supposedly a massive wasp, and it seemed to be directing the workers on the surface.\n\nI don't know much about these things, but if they're starting to wander beyond that pit in the ground, we need to put a stop to it. Kill this giant wasp and return to me.", completion = "Well done, {name}! You're proving very valuable to securing this area for the Alliance.", objectives = "Kill Stinglasher in the Writhing Deep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25432] = { id = 25432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Not \"Ogre\" Yet", description = "We dealt the Gordunni ogres a large blow at Dire Maul, but we haven't quite finished the job. My scouts have reported a group of them amassed in the hills to the north, gathering for some reason.\n\nIt's possible they're interested in the Horde settlement nearby, but I don't want to take any chances. Scout the area, kill any ogres you come across, and report back.", progress = "Be sure to strike a few down during your scouting. We should be efficient.", completion = "It's good to see you back. We've learned more about the ogre situation.", objectives = "Kill 5 Gordunni Hillguards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25433] = { id = 25433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sasquatch Sighting", description = "You may have seen it yourself, but other scouts have discovered an enormous beast being held by the ogres. Reports say it looks like a sasquatch, but if it is, it's the biggest ever seen in Feralas.\n\nThe ogres are most likely trying to teach it to obey them. While that's almost comical, I'm not going to sit by and let them train that thing to roll over at their command. Return to the hills and slay it.", completion = "Well done once again, {name}. Yet another threat removed from Feralas.", objectives = "Kill Bigfist.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25434] = { id = 25434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming The Tamers", description = "The sasquatch may be a larger threat, but we also need to wipe out the ogres. The Gordunni have been a nuisance to us for too long, and Lady Shandris wants them completely gone.  Let's hope these are the last ones.\n\nKill the Gordunni tamers that keep the beast chained, and make sure they know the price of their meddling.", completion = "Good work, and good riddance. I hope we never have to see another ogre here again!", objectives = "Kill 6 Gordunni Tamers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25435] = { id = 25435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pressure is Mounting", description = "G'day, <laddie/lassie>.\n\nThe name's Rendel.\n\nSeems ol' Moanah and I got here in the nick of time, eh?\n\nErunak wasn't kiddin' when he said it was life or death!\n\nWhile he's tryin' to find us a safe place to hole up, I'm gunna take a stab at securin' you a critter to ride.\n\nNow, I may not be up on all the ins an' outs of life in the sea, but it looked to me like them naga know how to get around down here.\n\nYou round up a few widgets for a bridle and I'll work up an enchantment.", objectives = "Collect 3 Shark Sinews from Ravenous Threshers and 2 Sharpened Crab Claws from Sabreclaw Skitterers.\n\nRavenous Threshers can also be summoned to you by using Crab Entrails.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25436] = { id = 25436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiteful Sisters", description = "Something truly disturbing has occured. While on patrol, several of my scouts were ambushed by dryads.\n\nThe dryads are close allies of the night elves and guardians of the forest. I assumed they were just frightened by the sight of worgen, but the sentinels I sent out afterwards were also attacked.\n\nWhatever is going on, I don't like it. I want you to go investigate as well. If even the dryads have been corrupted...put them to the sword.", completion = "I didn't want to scare you, but this is a grave situation. If the portal at Dream Bough was sealed, and the corruption is still spreading...", objectives = "Kill 8 Corrupted Dryads.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25437] = { id = 25437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ysondre's Call", description = "A dragon of the emerald dream... what have you gotten yourself involved in, {name}?\n\nI wouldn't keep her waiting if I were you. The place she spoke of is what we call the Emerald Summit. A path off the main road through the Lower Wilds leads up one of the high stone plateaus; there's a small shrine at the top.\n\nGood luck, {name}. I hope to see you back safe.", completion = "You've come.\n\nI am ashamed to ask this of you, {class}, but I've ran from him long enough. Taerar must be stopped.", objectives = "Speak with Ysondre atop the Emerald Summit in the Lower Wilds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25438] = { id = 25438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ysondre's Farewell", description = "With that, I am the only one left.\n\nEven if I choose to remain in this world, I cannot rejoin the green flight. But this victory gives me hope. Perhaps, in time, I can find peace in a simple life among mortals.\n\nYou must return to your people. Tell them that the dragons of nightmare are gone, and will no longer threaten these lands.", completion = "To be drawn into a fight between dragons...I don't know if you're blessed or cursed.\n\nLady Shandris has heard of all you've done, and has personally sent this reward for your bravery. I'm glad you came back in one piece to receive it.", objectives = "Speak to Adella at Shadebough.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25439] = { id = 25439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeful Heart", description = "These are the naga that took our people. I only need one to interrogate, kill the rest.\n\nShow no mercy, {class}, for they would surely show us none.", completion = "Good to have a real warrior at my side. Too often, my shaman brethren can't seem to stomach the work.", objectives = "Kill 10 Zin'jatar Ravagers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25440] = { id = 25440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fathom-Lord Zin'jatar", description = "The Fathom-Lord is here, at the far side of the ruins. He's still injured from our last battle.\n\nI'll leave this pleasure to you. Make sure he doesn't get away this time.", completion = "And with this, hopefully their attacks on us will calm for a while.", objectives = "Kill Fathom-Lord Zin'jatar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25441] = { id = 25441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vortex", description = "I have no fondness for snakes, and even less so down here. Fortunately for us, the watery elements still bend to my will for now.\n\nTake these globes and throw them at the ground to send the nearby water into a vortex, pulling in all the nearby serpents. The naga will most certainly turn the snakes against us, so keep the orbs close at hand.", completion = "Too often, we are mistaken for druidic types. Perhaps that's true for some shaman, but do not let yourself be plagued by the ignorant belief that we are always peaceful.\n\nNothing about what I do is harmonious. I command the elements to my will. There is nothing offered in return. I would have it no other way.", objectives = "Use the Globes of Tumultuous Water to trap 30 swarming serpents.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25442] = { id = 25442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Pearl of Wisdom", description = "This pearl is unlike anything you've ever seen before. It radiates light, and if you are not mistaken, it radiates powerful magic as well.\n\nEarthmender Duarn back in Silver Tide Hollow will surely be interested in this.", progress = "Yes, {class}? Have you found something?", completion = "What is this? A pearl? Much more I think.\n\nThis is exactly what I was looking for, thank you for bringing it to me.", objectives = "Bring the Luminescent Pearl to Earthmender Duarn in Silvertide Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25443] = { id = 25443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Name Never Spoken", description = "Did my drought work? You spoke with one of them?\n\nThen you know what to do. The name of their elemental master is written on three firestones scattered throughout the Inferno. Examine each of these stones and we will have the name we need.\n\nHurry! Your precious forest burns!", completion = "Yes, yes! Show me the runes you discovered.\n\n\"Vol'talo Thol'embaar.\" That's the name of your real enemy.\n\nPresumably you're dealing with one of Ragnaros's generals, sent here to scorch the mountainside and pave the way for his conquest.\n\nI will show you how to crush him.", objectives = "Assemble the true name by examining the three Firestones in the Inferno.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25444] = { id = 25444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Da Perfect Spies", description = "Now, it would be foolish to go in blind 'ere, so I be creatin' some tiny spies to gather information for Vol'jin. He got to know what's goin' on over on de islands.\n\nI could use da help, if you be feelin' up to it. I tell ya how it's done. First, ya gotta catch de frogs. Dey like to stay in de shade of da palm trees around Sen'jin.\n\nOnce ya have de frogs, bring 'em over here to my sentry totem an' attune dem to me sight.", objectives = "Capture 5 Sen'jin Frogs and attune them to Vanira's sight at her Sentry Totem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25445] = { id = 25445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zalazane's Fall", description = "De time for battle is now!  We'd be headin' ova to da islands soon, so you'd betta be ready.\n\nZalazane doesn't have much time left.", objectives = "Help Vol'jin take back the Echo Isles and kill Zalazane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25446] = { id = 25446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frogs Away!", description = "Wit de frogs ready to go, I be needin' ya to help me send 'em out to the isles.\n\nOn de eastern side of Sen'jin Village, ya can find Handler Marnlek. He be handlin' all the bats for Vol'jin's scouts and he can loan ya a bat to get ya out to de isles.\n\nTake dis sack' o frogs with ya. I been askin' de spirits for guidance. Dey've sent smoke to show ya where I need de eyes most. While ridin' de bat, reach into de sack and toss de frogs toward de white smoke.", objectives = "While riding a bat, use the Sack o' Frogs to place 12 attuned frogs on the markers in the Echo Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25447] = { id = 25447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signs of Change", description = "A severe illness has fallen over the creatures of this forest. While at first I hoped it was part of nature's course, it has refused to pass.\n\nThe forest stags, normally strong and serene, have suffered the worst. Some waste away in weakness; others froth and rage dangerously. If I am to consult the spirits to learn more of this sickness, I will need the stags' antlers.", progress = "This is a sad task, {name}, but necessary.", completion = "At the very least, these creatures' suffering has ended. Let us hope their sacrifice will bring a stop to further pain.", objectives = "Collect 8 Infected Stag Antlers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25448] = { id = 25448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Northspring Menace", description = "My duty here is to watch over Telaron. Even without his meditation leaving him vulnerable, there's enough threats in this forest to keep both of us on our toes.\n\nThat's why it maddens me so much that I don't have the opportunity to leave camp. More harpies than I've ever seen infest the northwest...foul creatures, spreading their filth across the ancient ruins uncaringly.\n\nThey're a threat to this camp, and have no place in these lands. I'll pay you well if you get rid of them.", completion = "Thank you, {class}. That's one less distraction for me.", objectives = "Kill 6 Northspring Harpies and 6 Northspring Windcallers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25449] = { id = 25449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mark of Quality", description = "My philosophy on leatherworking is that the work must be the best quality possible - no compromises. Anyone who says that quality doesn't matter is trying to sell you ocean-front property in Dun Morogh!\n\nIn my latest pursuit of high-quality materials, I have run across thick yeti hides. The Yeti are native to Feralas, with many found in Rage Scar Hold to the northeast. I want some, and I'll give you a choice of one of my leather goods for a stack of ten.  If that sounds fair, then we're in business.", progress = "A stack of ten thick yeti hides will net you a choice of one of my crafted items.  Because I care about quality, I am able to ensure you'll get a good item!", completion = "Did you stop and examine the texture of these hides?  Properly treated, these hides could very well be stronger than iron.  Not many people know about these hides, and that in combination with the vast treating solutions I know will allow me to potentially make items with a true mark of quality... thanks to you, of course!\n\nAnd now, please choose from what I am able to offer you for your service!", objectives = "Collect 10 Thick Yeti Hides.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25450] = { id = 25450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Improved Quality", description = "It's funny how things change. The northern yetis used to yield the best hides, but these...there's been a decline in quality, it seems. Maybe something nearby is making them sick.\n\nLuckily, the Feral Scar yetis to the southeast have flourished. I bet their hides are even better than they used to be!\n\nI would reward you handsomely for a stack of ten of their hides; bring them to me here, and we'll finish our business.", progress = "These hides may not be as resilient as thorium, but they're nice and supple.", completion = "Excellent, excellent!  These are going to work out incredibly well - I can already tell that they're going to be much harder when properly cured.\n\nThanks again for your help {name}.  Here - please take one of my latest creations.", objectives = "Collect 10 Feral Scar Yeti Hides.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25451] = { id = 25451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pristine Yeti Hide", description = "You have found a pristine yeti hide that is exceptionally thick and sturdy - more so than even the ones you've seen from the yeti in Rage Scar.\n\nConsidering that Pratt McGrubben at the Feathermoon Stronghold is in the market for yeti hides, this particular one may be of considerable interest to him.", progress = "What's this, {name} - you've got something special for me?", completion = "Incredible!  You may have found the granddaddy of all yeti hides with this!\n\nYou better believe I'll pay you for it.  I normally don't pay that much for a single hide, but I'm pretty sure I can make something special from it.  Thanks for thinking of me on this, {name}!", objectives = "Bring the Pristine Yeti Hide to Pratt McGrubben at the Feathermoon Stronghold, Feralas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25452] = { id = 25452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mark of Quality", description = "I take pride in my leather work, and I feel it shows; quality should never be compromised.  Anyone who says that quality doesn't matter would also have you believe that the earth does not keep secrets!\n\nIn my latest pursuit of high-quality materials, I have discovered thick yeti hides.  Yetis are native to Feralas, often found north of here in Rage Scar Hold.  I'll give you a choice of one of my leather goods for a stack of ten.  If that is agreeable to you, then we are set!", progress = "Were you able to get a stack of ten thick yeti hides?  My leather goods are second to none, and I'll share a sampling with you should you have the hides.", completion = "Ah, excellent!  These hides, when given a special treatment, are as resilient as iron I tell you!  It will take many tries in order to get the right mix down for the tanning, but I am confident they will bring my mark of quality to the next level.\n\nAs for you, {name}... your assistance has proven invaluable to me.  Please take your choice from these items I have crafted.", objectives = "Collect 10 Thick Yeti Hides.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25453] = { id = 25453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Improved Quality", description = "I'm a bit confused. The Rage Scar yeti used to be the finest source of leather in these lands... but these pelts are weak and even rotted in spots. Some sort of illness must be plaguing the creatures.\n\nI'll have to rely on a different source. The yeti of Feral Scar Vale to the south have hides nearly as strong. They are also a great deal fiercer; do not hunt them without caution, {class}.", progress = "Are the Feral Scar yeti still there? Did you get the leather?", completion = "Excellent, excellent!  These are going to work out incredibly well - I can already tell that they're going to be much harder when properly cured.\n\nThanks again for your aid, {name}.  Here - please take one of my latest creations.", objectives = "Collect 10 Feral Scar Yeti Hides from Feral Scar Yeti.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25454] = { id = 25454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perfect Yeti Hide", description = "You have found what may very well be a perfect yeti hide.  You easily note that it is exceptionally thick and sturdy - more so than even the ones you've seen from the yeti in Rage Scar.\n\nConsidering that Jangdor Swiftstrider at Stonemaul Hold is in the market for yeti hides, this particular one may be of considerable interest to him.", progress = "What's this, {name} - you've got something special for me?", completion = "This is an incredible find!  I believe this is the finest yeti hide specimen I have ever seen!\n\nIndeed, this is certainly worthy of an appropriate bounty.  I normally don't pay that much for a single hide, but I'm confident I can make something special from it.  Thanks for thinking of me on this, {name}!", objectives = "Bring the Perfect Yeti Hide to Jangdor Swiftstrider at Stonemaul Hold in Feralas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25455] = { id = 25455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Test of Wills", description = "Arright, <laddie/lassie> here we go.\n\nYou just need to sneak up on one 'a them naga while they ain't lookin' and use this bridle on 'em.\n\nDon't get too close, now! Ya gotta surprise 'em.\n\nDo it right an' get 'em under your control, and it'll be time ta show 'em who's boss!\n\nJust keep yankin' the reins 'til their will is broken, and you'll have yerself a fancy ride!\n\nGo on, now. Go git you one! I think I can see one just north 'a here...", objectives = "Use Erunak's Bridle to captivate a Zin'jatar Raider, then yank its reins until it submits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25456] = { id = 25456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back in One Piece", description = "Yeah yeah, I'm sure Felora wants you back. That woman has no respect for innovation. When I told her about the modifications I was making for my Earth Elemental, she nearly threw a fit.\n\nGo tell her everything's all well and dandy. And tell her she's not getting a share of my inevitable fortune either.\n\nShe probably likes sleeping on the rock anyway.", completion = "Sam's in one piece then? And his poor assistant Felice? Good to hear.\n\nI hope that one day he'll learn to respect the elements as more than just a tool.", objectives = "Return to Felora Firewreath in Silver Tide Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25457] = { id = 25457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ron Targetting Test", description = "Complete this quest." }
quests[25458] = { id = 25458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "General Skessesh", description = "The leader of these forces must fall! The naga's offensive will be broken with no one to command them.\n\nI saw the coward retreat into one of the abandoned buildings here. Cut your way through the others and take his head! Lady Shandris will want to see it for herself.", progress = "Has the general fallen?", completion = "Good riddance to foul creatures. May the naga slither back into the sea and never return.\n\nYou've proven yourself on the battlefield, {name}. I would ask more assistance of you in defending our lands here.", objectives = "Slay General Skessesh and take his head.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25459] = { id = 25459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ophidophobia", description = "If there's one thing I can't stand, it's snakes. Any kind of snake - doesn't matter.\n\nWhile I was out searching for salvage, I saw a nest of sea serpents surrounding the nearby wreckage.\n\nI simply can't relax knowing that those awful creatures could slither up in here at any moment.\n\nPlease, {class}! Do something about them!", completion = "Well that's a load off my mind.\n\nThank you again, {class}.", objectives = "Kill 4 Brinescale Serpents at Gorrok's Lament.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25460] = { id = 25460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Earth Rises", description = "The effects of the Twilight's Hammer attack can be felt even here, this close to the world tree.\n\nAs our forests burn, the very earth turns against us in a crazed frenzy.\n\nWe can't allow the elementals to go unchecked.  Go and help our men take care of them.", completion = "I thank you, {name}.  Your fighting prowess is admirable.  You will be crucial to putting a halt to the elemental onslaught.", objectives = "Slay 8 Scalding Rock Elementals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25461] = { id = 25461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollin' For Volunteers", description = "Vol'jin has given me his war drums and put  me in charge of trainin' da new recruits here. Only problem is we be short on new recruits.\n\nSupposin' I loaned ya dis drum, would ya use it to sound de call to war on Vol'jin's behalf in Razor Hill? If ya could even inspire just a few trolls to join da cause, it would make a difference. Once ya've convinced dem to volunteer, bring dem back to me for trainin'. Go over an' talk to Handler Marnlek to de south. He can lend you a bat for de ride to Razor Hill.", objectives = "Use Vol'jin's War Drums to recruit 5 Troll Citizens in Razor Hill.\n\nYou can speak to Handler Marnlek for a bat ride to Razor Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25462] = { id = 25462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bears Up There", description = "Do not fear the bears in this grove, {class} - I have pacified them for the moment.\n\nMy concern at present is for the welfare of the bear cubs. The fires drove the little ones up the trees, where they've gotten stuck. We've got to get those bears safely to the ground!\n\nFlying creatures frighten them, so you'll have to climb the trees yourself. Look for footholds at the trunks. Climb the trees, grab the bear cubs, and toss them - GENTLY! - onto the target here.\n\nNothing can go wrong with this plan.", progress = "Please don't hurt the trees. Or the bears.\n\nOr yourself.", completion = "I thank you, {name}. Those little bears are shaken up but they'll survive.\n\nAt least the ones that hit the mat.", objectives = "Climb up trees in the Whistling Grove, grab stranded Hyjal Bear Cubs, and then hurl them at the Soft Target from the top of the tree. This is perfectly safe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25463] = { id = 25463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Silvia", description = "A Highborne mage named Estulan, estranged from his surviving brothers, has built a tower to the east where he trains young night elves in arcane magic.\n\nWere it not for Lady Tyrande's recent mercy towards his kind, his execution would be my duty under the law. He will be watched closely, but I will not deny aid to my Sentinels simply out of pride.\n\nI've sent Silvia ahead to the Tower of Estulan to begin an offensive against the ogres infesting the nearby forest. Report to her for further orders.", completion = "Good to see you here. Estulan is being...difficult. We're going to have to deal with these ogres for Lady Shandris on our own until he decides to deal with us.", objectives = "Report to Silvia at the Tower of Estulan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25464] = { id = 25464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Return of Baron Geddon", description = "Ragnaros is not the only powerful elemental that has re-emerged into our world.\n\nThe dreaded Baron Geddon is leading the onslaught and we must put an end to this rampage.\n\nThe Flameseer's Staff has proven powerful.  Perhaps it is powerful enough to weaken him to the point where our arch druids can bind him where he stands.\n\nGo, {name} and be careful.  Baron Geddon is a vengeful and treacherous being.", progress = "Is it done yet, {name}?", completion = "Well done, {name}.  We cannot afford to lose any further ground in Hyjal.\n\nBy stopping Baron Geddon we will have dealt a huge blow to the enemy.", objectives = "Channel the Flameseer's Staff to weaken Baron Geddon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
